insert into public.questions (exam_category, subject, topic, type, difficulty, body, body_hi, question_data, options, marks_correct, marks_wrong, explanation, explanation_hi, concept_group_id, source_type, source_citation, status)
values
('upsc','Quantitative Aptitude','Number Theory','mcq','medium','Which one of the following is the largest?','निम्नलिखित में से कौन-सा सबसे बड़ा है?','{"craft": "inference", "csat_set": "csat-l4-s08", "csat_order": 1}'::jsonb,'[{"id": "a", "body": "(2³)²", "body_hi": "(2³)²", "isCorrect": false}, {"id": "b", "body": "3 raised to the power 2²", "body_hi": "3 की घात 2²", "isCorrect": false}, {"id": "c", "body": "(3²)²", "body_hi": "(3²)²", "isCorrect": false}, {"id": "d", "body": "2 raised to the power 3²", "body_hi": "2 की घात 3²", "isCorrect": true}]'::jsonb,2.5,0.83,'A power whose index is itself a power is worked from the top down: 2 raised to the power 3² is 2⁹ = 512. With brackets the inner power comes first, and the indices multiply: (2³)² = 2⁶ = 64 and (3²)² = 3⁴ = 81; and 3 raised to the power 2² is 3⁴ = 81. The trap is to read 2 raised to the power 3² as if it were (2³)², which gives only 64.','जिस घात का घातांक स्वयं एक घात हो, उसे ऊपर से नीचे की ओर हल करते हैं: 2 की घात 3², 2⁹ = 512 है। कोष्ठक होने पर भीतर की घात पहले आती है और घातांक गुणा होते हैं: (2³)² = 2⁶ = 64 और (3²)² = 3⁴ = 81; और 3 की घात 2², 3⁴ = 81 है। जाल यह है कि 2 की घात 3² को (2³)² की तरह पढ़ा जाए, जिससे केवल 64 मिलता है।','csat-l4-s08-qa-nt-powers-stacked-two-ways','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Permutation & Combination','mcq','medium','In how many ways can the letters of the word MOTHER be arranged so that the vowels always stand in even places (the 2nd, 4th or 6th)?','शब्द MOTHER के अक्षरों को कितने प्रकार से व्यवस्थित किया जा सकता है कि स्वर सदा सम स्थानों (दूसरे, चौथे या छठे) पर रहें?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s08", "csat_order": 2}'::jsonb,'[{"id": "a", "body": "36", "body_hi": "36", "isCorrect": false}, {"id": "b", "body": "48", "body_hi": "48", "isCorrect": false}, {"id": "c", "body": "72", "body_hi": "72", "isCorrect": false}, {"id": "d", "body": "144", "body_hi": "144", "isCorrect": true}]'::jsonb,2.5,0.83,'The vowels O and E go into two of the three even places: 3 × 2 = 6 ways. The four consonants M, T, H and R then fill the four places left, in 4! = 24 ways. In all, 6 × 24 = 144. 48 = 2 × 24 lets the vowels use only one fixed pair of even places; 72 halves the answer, as if O and E could not change places; 36 has no basis.','स्वर O और E तीन सम स्थानों में से दो में जाते हैं: 3 × 2 = 6 प्रकार। फिर चार व्यंजन M, T, H और R बचे चार स्थान 4! = 24 प्रकार से भरते हैं। कुल 6 × 24 = 144। 48 = 2 × 24 स्वरों को सम स्थानों की केवल एक निश्चित जोड़ी देता है; 72 उत्तर को आधा करता है, मानो O और E आपस में स्थान न बदल सकें; 36 का कोई आधार नहीं।','csat-l4-s08-qa-pc-the-vowels-of-mother-in-the-even-places','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Ratio, Mixtures & Alligation','statement_based','hard','Two hospitals treated patients with the same illness last year. Hospital P treated 100 mild cases, of whom 95 recovered, and 500 severe cases, of whom 300 recovered. Hospital Q treated 500 mild cases, of whom 450 recovered, and 100 severe cases, of whom 50 recovered. Which of the following statements is/are correct?','पिछले वर्ष दो अस्पतालों ने एक ही बीमारी के रोगियों का उपचार किया। अस्पताल P ने 100 हल्के मामलों का उपचार किया, जिनमें 95 ठीक हुए, और 500 गंभीर मामलों का, जिनमें 300 ठीक हुए। अस्पताल Q ने 500 हल्के मामलों का उपचार किया, जिनमें 450 ठीक हुए, और 100 गंभीर मामलों का, जिनमें 50 ठीक हुए। निम्नलिखित में से कौन-सा/से कथन सही है/हैं?','{"statements": ["P''s recovery rate was higher than Q''s both for mild cases and for severe cases.", "P''s recovery rate over all its patients was higher than Q''s."], "statements_hi": ["हल्के और गंभीर, दोनों प्रकार के मामलों में P की स्वस्थ होने की दर Q से अधिक थी।", "अपने सभी रोगियों को मिलाकर P की स्वस्थ होने की दर Q से अधिक थी।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s08", "csat_order": 3}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'1 is correct: for mild cases P had 95% against Q''s 90%, and for severe cases 60% against 50%. 2 is wrong: over all patients P had 395 of 600 recover (about 66%) and Q 500 of 600 (about 83%). The reversal comes from the mix of cases: most of P''s patients were severe, most of Q''s mild. So a hospital can do better in every group and still look worse overall -- which is why such rates should be compared group by group.','1 सही है: हल्के मामलों में P की दर 95% थी और Q की 90%, गंभीर मामलों में 60% और 50%। 2 ग़लत है: सभी रोगियों में P के 600 में से 395 ठीक हुए (लगभग 66%) और Q के 600 में से 500 (लगभग 83%)। यह उलटफेर मामलों के मिश्रण से आता है: P के अधिकांश रोगी गंभीर थे, Q के अधिकांश हल्के। इसलिए कोई अस्पताल हर समूह में बेहतर होकर भी कुल मिलाकर ख़राब दिख सकता है -- इसीलिए ऐसी दरों की तुलना समूह-दर-समूह करनी चाहिए।','csat-l4-s08-qa-rm-a-hospital-better-in-each-group-but-not-overall','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Direction & Distance','mcq','medium','A river flows from south to north. Ravi stands on its left bank -- the bank on the left of a person who faces downstream -- and turns to face upstream. On which side of Ravi is the river?','एक नदी दक्षिण से उत्तर की ओर बहती है। रवि उसके बाएँ तट पर खड़ा है -- वह तट जो धारा की दिशा में मुँह किए व्यक्ति के बाईं ओर होता है -- और प्रवाह के विपरीत दिशा में मुँह कर लेता है। नदी रवि की किस ओर है?','{"craft": "inference", "csat_set": "csat-l4-s08", "csat_order": 4}'::jsonb,'[{"id": "a", "body": "On his right", "body_hi": "उसके दाईं ओर", "isCorrect": false}, {"id": "b", "body": "In front of him", "body_hi": "उसके सामने", "isCorrect": false}, {"id": "c", "body": "Behind him", "body_hi": "उसके पीछे", "isCorrect": false}, {"id": "d", "body": "On his left", "body_hi": "उसके बाईं ओर", "isCorrect": true}]'::jsonb,2.5,0.83,'Facing downstream means facing north, and a person facing north has the west on their left, so the left bank is the west bank and the river lies to the east of Ravi. Facing upstream, Ravi faces south, and for someone facing south the east is on the left. So the river is on his left. The trap is to assume that a ''left bank'' keeps the river on one''s right whichever way one faces; the river runs alongside him, so it is neither in front nor behind.','धारा की दिशा में मुँह करने का अर्थ उत्तर की ओर मुँह करना है, और उत्तर की ओर मुँह किए व्यक्ति के बाईं ओर पश्चिम होता है, इसलिए बायाँ तट पश्चिमी तट है और नदी रवि के पूर्व में है। प्रवाह के विपरीत मुँह करने पर रवि दक्षिण की ओर देखता है, और दक्षिण की ओर देखने वाले के बाईं ओर पूर्व होता है। अतः नदी उसके बाईं ओर है। जाल यह मानना है कि ''बायाँ तट'' होने से नदी हर दिशा में दाईं ओर रहती है; नदी उसके साथ-साथ बहती है, इसलिए न सामने है न पीछे।','csat-l4-s08-lr-dd-the-left-bank-of-a-river-that-flows-north','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Between 1924 and 1927, engineers at the Hawthorne Works, a factory of the Western Electric Company near Chicago, tried to find out how lighting affected the output of workers. They raised the light for one group and kept it steady for a comparison group. Output rose in both. When the light was later lowered for the test group, output held up until the workers could barely see. Studies in a separate test room at the same factory, which changed rest breaks and working hours, found output rising with almost every change. Decades afterwards the term ''Hawthorne effect'' was coined for the idea that people change their behaviour simply because they know they are being studied, and the lesson usually drawn is that a study needs a comparison group that receives the same attention but not the treatment. Yet scholars who went back to the records found the original results weaker than the legend suggests. In the best-known test room, for instance, the workers were paid according to the output of their small group, and two of the five were replaced partway through.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1924 से 1927 के बीच शिकागो के पास वेस्टर्न इलेक्ट्रिक कंपनी के एक कारख़ाने, हॉथॉर्न वर्क्स, में इंजीनियरों ने यह जानने का प्रयास किया कि रोशनी श्रमिकों के उत्पादन को कैसे प्रभावित करती है। उन्होंने एक समूह के लिए रोशनी बढ़ाई और एक तुलना-समूह के लिए उसे स्थिर रखा। दोनों में उत्पादन बढ़ा। जब बाद में परीक्षण-समूह की रोशनी घटाई गई, तो उत्पादन तब तक बना रहा जब तक श्रमिक मुश्किल से देख पाने लगे। उसी कारख़ाने के एक अलग परीक्षण-कक्ष के अध्ययनों में, जिनमें विश्राम के अंतराल और काम के घंटे बदले गए, लगभग हर बदलाव के साथ उत्पादन बढ़ता पाया गया। दशकों बाद इस विचार के लिए ''हॉथॉर्न प्रभाव'' शब्द गढ़ा गया कि लोग केवल यह जानकर अपना व्यवहार बदल लेते हैं कि उनका अध्ययन हो रहा है, और इससे प्रायः यह सीख निकाली जाती है कि अध्ययन में ऐसा तुलना-समूह होना चाहिए जिसे उतना ही ध्यान मिले पर उपचार नहीं। फिर भी जिन विद्वानों ने अभिलेखों को दोबारा देखा, उन्होंने मूल परिणामों को किंवदंती से कमज़ोर पाया। उदाहरण के लिए, सबसे प्रसिद्ध परीक्षण-कक्ष में श्रमिकों को उनके छोटे समूह के उत्पादन के अनुसार भुगतान मिलता था, और पाँच में से दो को बीच में बदल दिया गया था।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s08", "passage_group": "csat-l4-s08-p01", "csat_order": 5}'::jsonb,'[{"id": "a", "body": "Better lighting in a factory raises the output of its workers, whatever else changes at the same time.", "body_hi": "कारख़ाने में बेहतर रोशनी श्रमिकों का उत्पादन बढ़ाती है, उसी समय और कुछ भी बदले।", "isCorrect": false}, {"id": "b", "body": "Studies of workers are of no value, since people always behave differently when they are watched.", "body_hi": "श्रमिकों के अध्ययनों का कोई मूल्य नहीं, क्योंकि देखे जाने पर लोग सदा अलग व्यवहार करते हैं।", "isCorrect": false}, {"id": "c", "body": "How workers are paid matters more than lighting or rest breaks in deciding how much they produce.", "body_hi": "श्रमिक कितना उत्पादन करते हैं, यह तय करने में रोशनी या विश्राम से अधिक महत्त्व भुगतान के ढंग का है।", "isCorrect": false}, {"id": "d", "body": "A famous lesson about the effect of being studied rests on evidence weaker than its fame suggests.", "body_hi": "अध्ययन किए जाने के प्रभाव की प्रसिद्ध सीख उतने मज़बूत प्रमाण पर नहीं टिकी जितनी प्रसिद्ध है।", "isCorrect": true}]'::jsonb,2.5,0.83,'The passage tells how the Hawthorne studies gave rise to a famous lesson about the effect of being studied, then shows that the records behind it are weaker than the legend. It reports that output rose even when the light was lowered, so better lighting is not its point; it says studies need comparison groups, not that studies of workers are worthless; and pay is mentioned as one thing that clouds the results, not as the main cause of output.','परिच्छेद बताता है कि हॉथॉर्न अध्ययनों से अध्ययन किए जाने के प्रभाव के बारे में एक प्रसिद्ध सीख कैसे निकली, फिर दिखाता है कि उसके पीछे के अभिलेख किंवदंती से कमज़ोर हैं। वह बताता है कि रोशनी घटाने पर भी उत्पादन बढ़ा, इसलिए बेहतर रोशनी उसकी बात नहीं; वह कहता है कि अध्ययनों में तुलना-समूह चाहिए, यह नहीं कि श्रमिकों के अध्ययन बेकार हैं; और भुगतान का उल्लेख परिणामों को धुँधला करने वाली एक बात के रूप में है, उत्पादन के मुख्य कारण के रूप में नहीं।','csat-l4-s08-rc-p01-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Between 1924 and 1927, engineers at the Hawthorne Works, a factory of the Western Electric Company near Chicago, tried to find out how lighting affected the output of workers. They raised the light for one group and kept it steady for a comparison group. Output rose in both. When the light was later lowered for the test group, output held up until the workers could barely see. Studies in a separate test room at the same factory, which changed rest breaks and working hours, found output rising with almost every change. Decades afterwards the term ''Hawthorne effect'' was coined for the idea that people change their behaviour simply because they know they are being studied, and the lesson usually drawn is that a study needs a comparison group that receives the same attention but not the treatment. Yet scholars who went back to the records found the original results weaker than the legend suggests. In the best-known test room, for instance, the workers were paid according to the output of their small group, and two of the five were replaced partway through.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1924 से 1927 के बीच शिकागो के पास वेस्टर्न इलेक्ट्रिक कंपनी के एक कारख़ाने, हॉथॉर्न वर्क्स, में इंजीनियरों ने यह जानने का प्रयास किया कि रोशनी श्रमिकों के उत्पादन को कैसे प्रभावित करती है। उन्होंने एक समूह के लिए रोशनी बढ़ाई और एक तुलना-समूह के लिए उसे स्थिर रखा। दोनों में उत्पादन बढ़ा। जब बाद में परीक्षण-समूह की रोशनी घटाई गई, तो उत्पादन तब तक बना रहा जब तक श्रमिक मुश्किल से देख पाने लगे। उसी कारख़ाने के एक अलग परीक्षण-कक्ष के अध्ययनों में, जिनमें विश्राम के अंतराल और काम के घंटे बदले गए, लगभग हर बदलाव के साथ उत्पादन बढ़ता पाया गया। दशकों बाद इस विचार के लिए ''हॉथॉर्न प्रभाव'' शब्द गढ़ा गया कि लोग केवल यह जानकर अपना व्यवहार बदल लेते हैं कि उनका अध्ययन हो रहा है, और इससे प्रायः यह सीख निकाली जाती है कि अध्ययन में ऐसा तुलना-समूह होना चाहिए जिसे उतना ही ध्यान मिले पर उपचार नहीं। फिर भी जिन विद्वानों ने अभिलेखों को दोबारा देखा, उन्होंने मूल परिणामों को किंवदंती से कमज़ोर पाया। उदाहरण के लिए, सबसे प्रसिद्ध परीक्षण-कक्ष में श्रमिकों को उनके छोटे समूह के उत्पादन के अनुसार भुगतान मिलता था, और पाँच में से दो को बीच में बदल दिया गया था।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["That output rose in the comparison group as well suggests that something other than the lighting was at work.", "The later look at the records showed that being studied has no effect on how people behave."], "statements_hi": ["तुलना-समूह में भी उत्पादन बढ़ना संकेत देता है कि रोशनी के अलावा कुछ और काम कर रहा था।", "अभिलेखों की बाद की जाँच ने दिखाया कि अध्ययन किए जाने का लोगों के व्यवहार पर कोई प्रभाव नहीं पड़ता।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s08", "passage_group": "csat-l4-s08-p01", "csat_order": 6}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Only 1 is valid. The comparison group''s lighting did not change, yet its output rose too, so the lighting cannot explain the rise and something else -- attention, pay, the changes in staff -- was at work. 2 goes too far: the scholars found the original results weaker than the legend, not proof that being studied has no effect at all.','केवल 1 वैध है। तुलना-समूह की रोशनी नहीं बदली, फिर भी उसका उत्पादन भी बढ़ा, इसलिए रोशनी उस बढ़त की व्याख्या नहीं कर सकती और कुछ और -- ध्यान, भुगतान, कर्मियों में बदलाव -- काम कर रहा था। 2 बहुत आगे चला जाता है: विद्वानों ने मूल परिणामों को किंवदंती से कमज़ोर पाया, यह प्रमाण नहीं कि अध्ययन किए जाने का कोई प्रभाव होता ही नहीं।','csat-l4-s08-rc-p01-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Specific Detail','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Between 1924 and 1927, engineers at the Hawthorne Works, a factory of the Western Electric Company near Chicago, tried to find out how lighting affected the output of workers. They raised the light for one group and kept it steady for a comparison group. Output rose in both. When the light was later lowered for the test group, output held up until the workers could barely see. Studies in a separate test room at the same factory, which changed rest breaks and working hours, found output rising with almost every change. Decades afterwards the term ''Hawthorne effect'' was coined for the idea that people change their behaviour simply because they know they are being studied, and the lesson usually drawn is that a study needs a comparison group that receives the same attention but not the treatment. Yet scholars who went back to the records found the original results weaker than the legend suggests. In the best-known test room, for instance, the workers were paid according to the output of their small group, and two of the five were replaced partway through.

According to the passage, which of the following clouds the results of the best-known test room?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1924 से 1927 के बीच शिकागो के पास वेस्टर्न इलेक्ट्रिक कंपनी के एक कारख़ाने, हॉथॉर्न वर्क्स, में इंजीनियरों ने यह जानने का प्रयास किया कि रोशनी श्रमिकों के उत्पादन को कैसे प्रभावित करती है। उन्होंने एक समूह के लिए रोशनी बढ़ाई और एक तुलना-समूह के लिए उसे स्थिर रखा। दोनों में उत्पादन बढ़ा। जब बाद में परीक्षण-समूह की रोशनी घटाई गई, तो उत्पादन तब तक बना रहा जब तक श्रमिक मुश्किल से देख पाने लगे। उसी कारख़ाने के एक अलग परीक्षण-कक्ष के अध्ययनों में, जिनमें विश्राम के अंतराल और काम के घंटे बदले गए, लगभग हर बदलाव के साथ उत्पादन बढ़ता पाया गया। दशकों बाद इस विचार के लिए ''हॉथॉर्न प्रभाव'' शब्द गढ़ा गया कि लोग केवल यह जानकर अपना व्यवहार बदल लेते हैं कि उनका अध्ययन हो रहा है, और इससे प्रायः यह सीख निकाली जाती है कि अध्ययन में ऐसा तुलना-समूह होना चाहिए जिसे उतना ही ध्यान मिले पर उपचार नहीं। फिर भी जिन विद्वानों ने अभिलेखों को दोबारा देखा, उन्होंने मूल परिणामों को किंवदंती से कमज़ोर पाया। उदाहरण के लिए, सबसे प्रसिद्ध परीक्षण-कक्ष में श्रमिकों को उनके छोटे समूह के उत्पादन के अनुसार भुगतान मिलता था, और पाँच में से दो को बीच में बदल दिया गया था।

परिच्छेद के अनुसार, निम्नलिखित में से कौन-सी बात सबसे प्रसिद्ध परीक्षण-कक्ष के परिणामों को धुँधला करती है?','{"craft": "precision", "csat_set": "csat-l4-s08", "passage_group": "csat-l4-s08-p01", "csat_order": 7}'::jsonb,'[{"id": "a", "body": "Its lighting was kept so dim that the workers'' output could not be measured.", "body_hi": "उसकी रोशनी इतनी मंद रखी गई कि श्रमिकों का उत्पादन मापा ही नहीं जा सका।", "isCorrect": false}, {"id": "b", "body": "Its workers were paid by their group''s output, and two of them were replaced.", "body_hi": "उसके श्रमिकों को समूह के उत्पादन से भुगतान मिलता था, और उनमें से दो बदले गए।", "isCorrect": true}, {"id": "c", "body": "It was run without any group or period against which to compare its output.", "body_hi": "वह बिना किसी ऐसे समूह या अवधि के चला जिससे उसके उत्पादन की तुलना की जा सके।", "isCorrect": false}, {"id": "d", "body": "Its workers were never told that their output was being recorded and studied.", "body_hi": "उसके श्रमिकों को कभी नहीं बताया गया कि उनका उत्पादन दर्ज और अध्ययन किया जा रहा है।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage names two things: the workers were paid by their small group''s output, and two of the five were replaced partway through -- either could have changed output on its own. It does not say the lighting there was too dim to measure output, that the room had no comparison at all, or that the workers did not know they were being studied.','परिच्छेद दो बातें बताता है: श्रमिकों को उनके छोटे समूह के उत्पादन से भुगतान मिलता था, और पाँच में से दो बीच में बदले गए -- इनमें से कोई भी अपने आप उत्पादन बदल सकती थी। वह यह नहीं कहता कि वहाँ रोशनी उत्पादन मापने के लिए बहुत मंद थी, कि कक्ष में कोई तुलना थी ही नहीं, या कि श्रमिकों को अध्ययन का पता नहीं था।','csat-l4-s08-rc-p01-what-clouds-the-best-known-test-room','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Time & Work','mcq','hard','A grill holds two slices of bread at a time and toasts one side of a slice in 2 minutes. Each slice must be toasted on both sides. What is the least time needed to toast three slices?','एक ग्रिल पर एक समय में ब्रेड के दो स्लाइस आते हैं और वह एक स्लाइस का एक तरफ़ 2 मिनट में सेंकती है। हर स्लाइस दोनों तरफ़ सेंकनी है। तीन स्लाइस सेंकने में कम से कम कितना समय लगेगा?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s08", "csat_order": 8}'::jsonb,'[{"id": "a", "body": "4 min", "body_hi": "4 मिनट", "isCorrect": false}, {"id": "b", "body": "6 min", "body_hi": "6 मिनट", "isCorrect": true}, {"id": "c", "body": "8 min", "body_hi": "8 मिनट", "isCorrect": false}, {"id": "d", "body": "12 min", "body_hi": "12 मिनट", "isCorrect": false}]'::jsonb,2.5,0.83,'There are 6 sides to toast and the grill does 2 at a time, so at least 3 rounds of 2 minutes are needed -- and 3 rounds are enough if no round is wasted: first A and B on side one; then A on side two and C on side one; then B and C on side two. That is 6 minutes. 8 min finishes A and B together and then leaves C alone on the grill for two rounds, with a space empty; 12 min toasts the slices one at a time; 4 min would toast only 4 of the 6 sides.','सेंकने को 6 तरफ़ हैं और ग्रिल एक बार में 2 सेंकती है, इसलिए कम से कम 2-2 मिनट के 3 दौर चाहिए -- और कोई दौर व्यर्थ न जाए तो 3 पर्याप्त हैं: पहले A और B की पहली तरफ़; फिर A की दूसरी और C की पहली तरफ़; फिर B और C की दूसरी तरफ़। यानी 6 मिनट। 8 मिनट A और B को साथ पूरा करके फिर C को दो दौर अकेले ग्रिल पर छोड़ता है, जिसमें एक जगह ख़ाली रहती है; 12 मिनट स्लाइसों को एक-एक करके सेंकता है; 4 मिनट में 6 में से केवल 4 तरफ़ सिंकतीं।','csat-l4-s08-qa-tw-three-slices-on-a-grill-that-holds-two','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Percentage & Profit-Loss','mcq','medium','A company whose shares have a face value of ₹10 each declares a dividend of 30%. An investor had bought its shares at the market price of ₹40 each. What return does the dividend give the investor on the money invested?','एक कंपनी, जिसके शेयरों का अंकित मूल्य ₹10 प्रति शेयर है, 30% लाभांश घोषित करती है। एक निवेशक ने उसके शेयर ₹40 प्रति शेयर के बाज़ार मूल्य पर ख़रीदे थे। लाभांश से निवेशक को लगाई गई राशि पर कितना प्रतिफल मिलता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s08", "csat_order": 9}'::jsonb,'[{"id": "a", "body": "3%", "body_hi": "3%", "isCorrect": false}, {"id": "b", "body": "7.5%", "body_hi": "7.5%", "isCorrect": true}, {"id": "c", "body": "12%", "body_hi": "12%", "isCorrect": false}, {"id": "d", "body": "30%", "body_hi": "30%", "isCorrect": false}]'::jsonb,2.5,0.83,'A dividend percentage is reckoned on the face value: 30% of ₹10 = ₹3 a share. The investor paid ₹40 a share, so the return is 3 ÷ 40 = 7.5%. 30% reads the dividend as a return on the price paid; 3% mistakes the ₹3 for a percentage; 12% multiplies 30% by 40/100 instead of scaling it by 10/40.','लाभांश का प्रतिशत अंकित मूल्य पर गिना जाता है: ₹10 का 30% = ₹3 प्रति शेयर। निवेशक ने ₹40 प्रति शेयर दिए, इसलिए प्रतिफल 3 ÷ 40 = 7.5% है। 30% लाभांश को चुकाए गए मूल्य पर प्रतिफल मान लेता है; 3%, ₹3 को प्रतिशत समझ लेता है; 12%, 30% को 10/40 से बदलने के बजाय 40/100 से गुणा करता है।','csat-l4-s08-qa-pp-a-dividend-on-the-face-value','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Statement-Conclusion/Assumption','mcq','easy','A museum guide tells visitors: ''This fossil is 65 million and 3 years old. When I started working here three years ago, I was told it was 65 million years old.'' Which one of the following best describes the error in the guide''s statement?','एक संग्रहालय का गाइड दर्शकों से कहता है: ''यह जीवाश्म 6 करोड़ 50 लाख और 3 वर्ष पुराना है। जब मैंने तीन वर्ष पहले यहाँ काम शुरू किया था, तब मुझे बताया गया था कि यह 6 करोड़ 50 लाख वर्ष पुराना है।'' निम्नलिखित में से कौन-सा गाइड के कथन की त्रुटि का सबसे अच्छा वर्णन करता है?','{"craft": "inference", "csat_set": "csat-l4-s08", "csat_order": 10}'::jsonb,'[{"id": "a", "body": "It assumes that a fossil goes on growing older after it has been dug out of the rock.", "body_hi": "यह मान लेता है कि चट्टान से निकाले जाने के बाद भी जीवाश्म और पुराना होता जाता है।", "isCorrect": false}, {"id": "b", "body": "It relies on what one person was told instead of on any record kept by the museum.", "body_hi": "यह संग्रहालय के किसी अभिलेख के बजाय उस पर निर्भर करता है जो एक व्यक्ति को बताया गया था।", "isCorrect": false}, {"id": "c", "body": "It confuses the age of the fossil with the length of time the museum has displayed it.", "body_hi": "यह जीवाश्म की आयु को उस अवधि से भ्रमित करता है जितने समय से संग्रहालय उसे प्रदर्शित कर रहा है।", "isCorrect": false}, {"id": "d", "body": "It adds an exact figure to a rough estimate, claiming a precision it never had.", "body_hi": "यह मोटे अनुमान में सटीक संख्या जोड़कर ऐसी सटीकता का दावा करता है जो उसमें कभी नहीं थी।", "isCorrect": true}]'::jsonb,2.5,0.83,'''65 million years'' is a round estimate, uncertain by far more than three years; adding 3 to it gives an air of exactness the original figure never had. The fossil does grow older with time, so that is not the error; the trouble is not whose word it is but the false precision; and the guide does not mix up the fossil''s age with how long it has been on display.','''6 करोड़ 50 लाख वर्ष'' एक गोल अनुमान है, जिसकी अनिश्चितता तीन वर्षों से कहीं अधिक है; उसमें 3 जोड़ना ऐसी सटीकता का आभास देता है जो मूल संख्या में कभी नहीं थी। जीवाश्म समय के साथ सचमुच पुराना होता है, इसलिए वह त्रुटि नहीं; कठिनाई यह नहीं कि बात किसकी है, बल्कि झूठी सटीकता है; और गाइड जीवाश्म की आयु को प्रदर्शन की अवधि से नहीं मिलाता।','csat-l4-s08-lr-sc-a-fossil-dated-to-the-year','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Speed-Distance-Time','mcq','medium','Two shots are fired from a train exactly 10 minutes apart, as it runs straight towards a man standing beside the track. The man hears the two shots 9 minutes 45 seconds apart. If sound travels at 330 m/s, what is the speed of the train?','एक रेलगाड़ी से ठीक 10 मिनट के अंतर पर दो गोलियाँ चलाई जाती हैं, जब वह पटरी के किनारे खड़े एक व्यक्ति की ओर सीधी चल रही है। व्यक्ति दोनों गोलियों की आवाज़ 9 मिनट 45 सेकंड के अंतर पर सुनता है। यदि ध्वनि 330 मी/से से चलती है, तो रेलगाड़ी की चाल क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s08", "csat_order": 11}'::jsonb,'[{"id": "a", "body": "8.25 km/h", "body_hi": "8.25 किमी/घंटा", "isCorrect": false}, {"id": "b", "body": "29.7 km/h", "body_hi": "29.7 किमी/घंटा", "isCorrect": true}, {"id": "c", "body": "30.5 km/h", "body_hi": "30.5 किमी/घंटा", "isCorrect": false}, {"id": "d", "body": "59.4 km/h", "body_hi": "59.4 किमी/घंटा", "isCorrect": false}]'::jsonb,2.5,0.83,'The second shot is fired nearer the man by the distance the train runs in 10 minutes, so its sound reaches him sooner by the time sound takes to cross that distance -- here 15 seconds. In 15 s sound covers 330 × 15 = 4,950 m, and the train covered those 4,950 m in 600 s: 8.25 m/s = 8.25 × 3.6 = 29.7 km/h. 8.25 km/h forgets to turn m/s into km/h; 30.5 km/h divides by the 585 seconds the man heard instead of the 600 the train ran; 59.4 km/h doubles the answer, as if the sound went out and back like an echo.','दूसरी गोली व्यक्ति के उतना निकट चलाई जाती है जितना रेलगाड़ी 10 मिनट में चलती है, इसलिए उसकी आवाज़ उतना पहले पहुँचती है जितना ध्वनि को वह दूरी पार करने में लगता है -- यहाँ 15 सेकंड। 15 से में ध्वनि 330 × 15 = 4,950 मी चलती है, और रेलगाड़ी ने ये 4,950 मी 600 से में तय किए: 8.25 मी/से = 8.25 × 3.6 = 29.7 किमी/घंटा। 8.25 किमी/घंटा मी/से को किमी/घंटा में बदलना भूल जाता है; 30.5 किमी/घंटा रेलगाड़ी के 600 सेकंड के बजाय व्यक्ति द्वारा सुने 585 सेकंड से भाग देता है; 59.4 किमी/घंटा उत्तर को दोगुना करता है, मानो ध्वनि प्रतिध्वनि की तरह जाकर लौटी हो।','csat-l4-s08-qa-sdt-two-shots-heard-closer-together','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In 1929 the economist Harold Hotelling asked why competing sellers so often end up side by side. Picture a straight beach with bathers spread evenly along it and two ice-cream sellers, each free to set up anywhere. Bathers walk to the nearer seller. If the sellers stood at the quarter-points, each would serve half the beach and no bather would walk more than a quarter of its length. But either seller can win customers by edging towards the middle, taking bathers from the rival''s side while keeping all of their own. So both drift to the centre and end up back to back, still sharing the beach equally, while bathers at the ends now walk twice as far. Economists later used the same reasoning for elections: two parties competing for votes may move towards the middle of opinion until their programmes look alike. The result depends on its assumptions, however. If bathers far from both sellers would rather go without than walk, or if a third seller arrives, the pull to the centre weakens or breaks down.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1929 में अर्थशास्त्री हैरल्ड होटेलिंग ने पूछा कि प्रतिस्पर्धी विक्रेता इतनी बार अगल-बग़ल क्यों आ जाते हैं। एक सीधे समुद्र-तट की कल्पना करें जिस पर स्नान करने वाले समान रूप से फैले हैं, और आइसक्रीम के दो विक्रेता, जिनमें से हर एक कहीं भी दुकान लगा सकता है। स्नान करने वाले निकट वाले विक्रेता तक चलकर जाते हैं। यदि विक्रेता चौथाई-बिंदुओं पर खड़े हों, तो हर एक आधे तट को सेवा देगा और किसी को तट की लंबाई के चौथाई से अधिक नहीं चलना पड़ेगा। पर कोई भी विक्रेता बीच की ओर खिसककर ग्राहक जीत सकता है -- प्रतिद्वंद्वी की ओर के स्नान करने वालों को लेते हुए और अपने सभी को रखते हुए। इसलिए दोनों केंद्र की ओर खिसकते हैं और पीठ से पीठ सटाकर खड़े हो जाते हैं, अब भी तट को बराबर बाँटते हुए, जबकि छोरों पर के लोगों को अब दोगुना चलना पड़ता है। अर्थशास्त्रियों ने बाद में यही तर्क चुनावों पर लगाया: वोटों के लिए प्रतिस्पर्धा करते दो दल विचारों के मध्य की ओर तब तक खिसक सकते हैं जब तक उनके कार्यक्रम एक जैसे न दिखने लगें। पर यह परिणाम अपनी मान्यताओं पर निर्भर है। यदि दोनों विक्रेताओं से दूर के लोग चलने के बजाय बिना आइसक्रीम रहना पसंद करें, या कोई तीसरा विक्रेता आ जाए, तो केंद्र का खिंचाव कमज़ोर पड़ जाता है या टूट जाता है।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s08", "passage_group": "csat-l4-s08-p02", "csat_order": 12}'::jsonb,'[{"id": "a", "body": "Competition may pull rivals to the same middle spot, though this rests on certain assumptions.", "body_hi": "प्रतिस्पर्धा प्रतिद्वंद्वियों को एक ही मध्य स्थान पर खींच सकती है, पर यह कुछ मान्यताओं पर टिका है।", "isCorrect": true}, {"id": "b", "body": "Sellers who stand side by side always charge higher prices than sellers who stand far apart.", "body_hi": "अगल-बग़ल खड़े विक्रेता दूर-दूर खड़े विक्रेताओं से सदा ऊँचे मूल्य लेते हैं।", "isCorrect": false}, {"id": "c", "body": "Political parties in every democracy end up offering exactly the same programmes to all their voters.", "body_hi": "हर लोकतंत्र के राजनीतिक दल अंततः मतदाताओं को बिल्कुल एक जैसे कार्यक्रम देते हैं।", "isCorrect": false}, {"id": "d", "body": "Bathers on a beach are served best when both ice-cream sellers stand at its very middle.", "body_hi": "समुद्र-तट पर लोगों को तब सबसे अच्छी सेवा मिलती है जब आइसक्रीम के दोनों विक्रेता ठीक बीच में खड़े हों।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage explains how competition for the same customers can pull two rivals to the same middle spot, applies this to elections, and ends by noting that the result rests on its assumptions. It says nothing about prices; it says parties ''may'' move to the middle, not that all parties in every democracy end up identical; and it says bathers are served worse, not best, when the sellers stand at the middle.','परिच्छेद समझाता है कि एक ही ग्राहकों के लिए प्रतिस्पर्धा दो प्रतिद्वंद्वियों को एक ही मध्य स्थान पर कैसे खींच सकती है, इसे चुनावों पर लगाता है, और यह कहकर समाप्त होता है कि परिणाम अपनी मान्यताओं पर टिका है। वह मूल्यों के बारे में कुछ नहीं कहता; वह कहता है कि दल मध्य की ओर ''खिसक सकते हैं'', यह नहीं कि हर लोकतंत्र के सभी दल एक जैसे हो जाते हैं; और वह कहता है कि विक्रेताओं के मध्य में खड़े होने पर लोगों को ख़राब, न कि सबसे अच्छी, सेवा मिलती है।','csat-l4-s08-rc-p02-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In 1929 the economist Harold Hotelling asked why competing sellers so often end up side by side. Picture a straight beach with bathers spread evenly along it and two ice-cream sellers, each free to set up anywhere. Bathers walk to the nearer seller. If the sellers stood at the quarter-points, each would serve half the beach and no bather would walk more than a quarter of its length. But either seller can win customers by edging towards the middle, taking bathers from the rival''s side while keeping all of their own. So both drift to the centre and end up back to back, still sharing the beach equally, while bathers at the ends now walk twice as far. Economists later used the same reasoning for elections: two parties competing for votes may move towards the middle of opinion until their programmes look alike. The result depends on its assumptions, however. If bathers far from both sellers would rather go without than walk, or if a third seller arrives, the pull to the centre weakens or breaks down.

Which one of the following would most weaken the pull of the two sellers towards the centre of the beach?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1929 में अर्थशास्त्री हैरल्ड होटेलिंग ने पूछा कि प्रतिस्पर्धी विक्रेता इतनी बार अगल-बग़ल क्यों आ जाते हैं। एक सीधे समुद्र-तट की कल्पना करें जिस पर स्नान करने वाले समान रूप से फैले हैं, और आइसक्रीम के दो विक्रेता, जिनमें से हर एक कहीं भी दुकान लगा सकता है। स्नान करने वाले निकट वाले विक्रेता तक चलकर जाते हैं। यदि विक्रेता चौथाई-बिंदुओं पर खड़े हों, तो हर एक आधे तट को सेवा देगा और किसी को तट की लंबाई के चौथाई से अधिक नहीं चलना पड़ेगा। पर कोई भी विक्रेता बीच की ओर खिसककर ग्राहक जीत सकता है -- प्रतिद्वंद्वी की ओर के स्नान करने वालों को लेते हुए और अपने सभी को रखते हुए। इसलिए दोनों केंद्र की ओर खिसकते हैं और पीठ से पीठ सटाकर खड़े हो जाते हैं, अब भी तट को बराबर बाँटते हुए, जबकि छोरों पर के लोगों को अब दोगुना चलना पड़ता है। अर्थशास्त्रियों ने बाद में यही तर्क चुनावों पर लगाया: वोटों के लिए प्रतिस्पर्धा करते दो दल विचारों के मध्य की ओर तब तक खिसक सकते हैं जब तक उनके कार्यक्रम एक जैसे न दिखने लगें। पर यह परिणाम अपनी मान्यताओं पर निर्भर है। यदि दोनों विक्रेताओं से दूर के लोग चलने के बजाय बिना आइसक्रीम रहना पसंद करें, या कोई तीसरा विक्रेता आ जाए, तो केंद्र का खिंचाव कमज़ोर पड़ जाता है या टूट जाता है।

निम्नलिखित में से कौन-सी बात दोनों विक्रेताओं के तट के केंद्र की ओर खिंचाव को सबसे अधिक कमज़ोर करेगी?','{"craft": "inference", "csat_set": "csat-l4-s08", "passage_group": "csat-l4-s08-p02", "csat_order": 13}'::jsonb,'[{"id": "a", "body": "Both sellers charge exactly the same price for ice-cream of exactly the same quality.", "body_hi": "दोनों विक्रेता बिल्कुल एक ही गुणवत्ता की आइसक्रीम का बिल्कुल एक ही मूल्य लेते हैं।", "isCorrect": false}, {"id": "b", "body": "The bathers on the beach are spread evenly along the whole of its length every day.", "body_hi": "तट पर के लोग हर दिन उसकी पूरी लंबाई में समान रूप से फैले रहते हैं।", "isCorrect": false}, {"id": "c", "body": "Each of the two sellers is free to move a stall along the beach at any time of day.", "body_hi": "दोनों में से हर विक्रेता दिन में किसी भी समय तट पर अपनी दुकान खिसका सकता है।", "isCorrect": false}, {"id": "d", "body": "Bathers at the far ends would buy no ice-cream at all rather than walk far.", "body_hi": "तट के दूर छोरों पर के लोग दूर चलने के बजाय आइसक्रीम ख़रीदेंगे ही नहीं।", "isCorrect": true}]'::jsonb,2.5,0.83,'A seller moves to the middle to win bathers without losing any. If bathers far from a seller would buy nothing rather than walk, then moving inwards loses the customers at the seller''s own end, and the gain from crowding the rival shrinks -- the passage names this as a case where the pull weakens. Equal prices, bathers spread evenly and sellers free to move are the very conditions under which the passage says the sellers drift to the centre; they strengthen the pull, not weaken it.','विक्रेता बीच की ओर इसलिए जाता है कि बिना किसी को खोए लोग जीते। यदि विक्रेता से दूर के लोग चलने के बजाय कुछ न ख़रीदें, तो भीतर की ओर जाने से विक्रेता अपने छोर के ग्राहक खो देता है, और प्रतिद्वंद्वी के पास सटने का लाभ घट जाता है -- परिच्छेद इसे ऐसी स्थिति बताता है जिसमें खिंचाव कमज़ोर पड़ता है। बराबर मूल्य, समान रूप से फैले लोग और खिसकने को स्वतंत्र विक्रेता वही परिस्थितियाँ हैं जिनमें परिच्छेद के अनुसार विक्रेता केंद्र की ओर जाते हैं; ये खिंचाव को मज़बूत करती हैं, कमज़ोर नहीं।','csat-l4-s08-rc-p02-what-weakens-the-pull-to-the-centre','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In 1929 the economist Harold Hotelling asked why competing sellers so often end up side by side. Picture a straight beach with bathers spread evenly along it and two ice-cream sellers, each free to set up anywhere. Bathers walk to the nearer seller. If the sellers stood at the quarter-points, each would serve half the beach and no bather would walk more than a quarter of its length. But either seller can win customers by edging towards the middle, taking bathers from the rival''s side while keeping all of their own. So both drift to the centre and end up back to back, still sharing the beach equally, while bathers at the ends now walk twice as far. Economists later used the same reasoning for elections: two parties competing for votes may move towards the middle of opinion until their programmes look alike. The result depends on its assumptions, however. If bathers far from both sellers would rather go without than walk, or if a third seller arrives, the pull to the centre weakens or breaks down.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1929 में अर्थशास्त्री हैरल्ड होटेलिंग ने पूछा कि प्रतिस्पर्धी विक्रेता इतनी बार अगल-बग़ल क्यों आ जाते हैं। एक सीधे समुद्र-तट की कल्पना करें जिस पर स्नान करने वाले समान रूप से फैले हैं, और आइसक्रीम के दो विक्रेता, जिनमें से हर एक कहीं भी दुकान लगा सकता है। स्नान करने वाले निकट वाले विक्रेता तक चलकर जाते हैं। यदि विक्रेता चौथाई-बिंदुओं पर खड़े हों, तो हर एक आधे तट को सेवा देगा और किसी को तट की लंबाई के चौथाई से अधिक नहीं चलना पड़ेगा। पर कोई भी विक्रेता बीच की ओर खिसककर ग्राहक जीत सकता है -- प्रतिद्वंद्वी की ओर के स्नान करने वालों को लेते हुए और अपने सभी को रखते हुए। इसलिए दोनों केंद्र की ओर खिसकते हैं और पीठ से पीठ सटाकर खड़े हो जाते हैं, अब भी तट को बराबर बाँटते हुए, जबकि छोरों पर के लोगों को अब दोगुना चलना पड़ता है। अर्थशास्त्रियों ने बाद में यही तर्क चुनावों पर लगाया: वोटों के लिए प्रतिस्पर्धा करते दो दल विचारों के मध्य की ओर तब तक खिसक सकते हैं जब तक उनके कार्यक्रम एक जैसे न दिखने लगें। पर यह परिणाम अपनी मान्यताओं पर निर्भर है। यदि दोनों विक्रेताओं से दूर के लोग चलने के बजाय बिना आइसक्रीम रहना पसंद करें, या कोई तीसरा विक्रेता आ जाए, तो केंद्र का खिंचाव कमज़ोर पड़ जाता है या टूट जाता है।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["Once both sellers stand at the centre, neither can gain customers by moving away.", "Taken together, the bathers walk farther when the sellers stand back to back than when they stand at the quarter-points."], "statements_hi": ["जब दोनों विक्रेता केंद्र पर खड़े हों, तो कोई भी दूर खिसककर ग्राहक नहीं जीत सकता।", "कुल मिलाकर, विक्रेताओं के पीठ से पीठ सटाकर खड़े होने पर लोग चौथाई-बिंदुओं वाली स्थिति से अधिक चलते हैं।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s08", "passage_group": "csat-l4-s08-p02", "csat_order": 14}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Both are valid. 1: once the sellers stand back to back at the centre, a seller who moves away gives up bathers to the rival without gaining any, so neither has a reason to move. 2: at the quarter-points no bather walks more than a quarter of the beach; at the centre those at the ends walk half of it, twice as far, and on average every bather walks farther. The passage notes the sellers still share the beach equally, so the bathers bear the whole cost.','दोनों वैध हैं। 1: जब विक्रेता केंद्र पर पीठ से पीठ सटाकर खड़े हों, तो दूर खिसकने वाला विक्रेता बिना कुछ पाए प्रतिद्वंद्वी को लोग दे देता है, इसलिए किसी के पास खिसकने का कारण नहीं। 2: चौथाई-बिंदुओं पर कोई व्यक्ति तट के चौथाई से अधिक नहीं चलता; केंद्र पर छोरों के लोग उसका आधा, यानी दोगुना, चलते हैं, और औसतन हर व्यक्ति अधिक चलता है। परिच्छेद बताता है कि विक्रेता तब भी तट बराबर बाँटते हैं, इसलिए पूरी लागत लोग उठाते हैं।','csat-l4-s08-rc-p02-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','medium','What is the value of 1³ + 2³ + 3³ + ... + 10³?','1³ + 2³ + 3³ + ... + 10³ का मान क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s08", "csat_order": 15}'::jsonb,'[{"id": "a", "body": "385", "body_hi": "385", "isCorrect": false}, {"id": "b", "body": "2,025", "body_hi": "2,025", "isCorrect": false}, {"id": "c", "body": "3,025", "body_hi": "3,025", "isCorrect": true}, {"id": "d", "body": "4,356", "body_hi": "4,356", "isCorrect": false}]'::jsonb,2.5,0.83,'The sum of the first n cubes is the square of the sum of the first n numbers: (1 + 2 + ... + 10)² = 55² = 3,025. (Check with a short case: 1³ + 2³ = 9 = 3².) 385 is the sum of the squares 1² to 10², not the cubes; 2,025 = 45² stops at 9³; 4,356 = 66² runs on to 11³.','पहले n घनों का योग पहली n संख्याओं के योग का वर्ग होता है: (1 + 2 + ... + 10)² = 55² = 3,025। (छोटे उदाहरण से जाँचें: 1³ + 2³ = 9 = 3²।) 385, घनों का नहीं बल्कि 1² से 10² तक के वर्गों का योग है; 2,025 = 45², 9³ पर रुक जाता है; 4,356 = 66², 11³ तक चला जाता है।','csat-l4-s08-qa-nt-the-cubes-from-1-to-10-added','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Syllogism','statement_based','medium','Statements: No drum is a flute. Some flutes are made of bamboo.

Which of the following conclusions follow(s) from the statements?','कथन: कोई ढोल बाँसुरी नहीं है। कुछ बाँसुरियाँ बाँस से बनी हैं।

निम्नलिखित में से कौन-सा/से निष्कर्ष कथनों से निकलता/निकलते है/हैं?','{"statements": ["Some things made of bamboo are not drums.", "Some drums are not made of bamboo."], "statements_hi": ["बाँस से बनी कुछ वस्तुएँ ढोल नहीं हैं।", "कुछ ढोल बाँस से नहीं बने हैं।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "numbering": "roman", "csat_set": "csat-l4-s08", "csat_order": 16}'::jsonb,'[{"id": "a", "body": "I only", "body_hi": "केवल I", "isCorrect": true}, {"id": "b", "body": "II only", "body_hi": "केवल II", "isCorrect": false}, {"id": "c", "body": "Both I and II", "body_hi": "I और II दोनों", "isCorrect": false}, {"id": "d", "body": "Neither I nor II", "body_hi": "न तो I, न ही II", "isCorrect": false}]'::jsonb,2.5,0.83,'Only I follows. The bamboo flutes are things made of bamboo, and since no drum is a flute, none of them is a drum. II does not follow: the statements say nothing about what drums are made of -- every drum might be made of bamboo without breaking either statement. II looks like I turned round, but ''some A are not B'' cannot be reversed.','केवल I निकलता है। बाँस की बाँसुरियाँ बाँस से बनी वस्तुएँ हैं, और चूँकि कोई ढोल बाँसुरी नहीं है, उनमें से कोई ढोल नहीं है। II नहीं निकलता: कथन यह नहीं बताते कि ढोल किससे बने हैं -- हर ढोल बाँस का हो सकता है और कोई कथन नहीं टूटता। II, I को उलटकर पढ़ने जैसा लगता है, पर ''कुछ A, B नहीं हैं'' को उलटा नहीं जा सकता।','csat-l4-s08-lr-sy-drums-flutes-and-bamboo','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Permutation & Combination','mcq','hard','Four different tasks are shared out among three volunteers so that each volunteer gets at least one task. In how many ways can this be done?','चार अलग-अलग काम तीन स्वयंसेवकों में इस प्रकार बाँटे जाते हैं कि हर स्वयंसेवक को कम से कम एक काम मिले। यह कितने प्रकार से किया जा सकता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s08", "csat_order": 17}'::jsonb,'[{"id": "a", "body": "24", "body_hi": "24", "isCorrect": false}, {"id": "b", "body": "33", "body_hi": "33", "isCorrect": false}, {"id": "c", "body": "36", "body_hi": "36", "isCorrect": true}, {"id": "d", "body": "81", "body_hi": "81", "isCorrect": false}]'::jsonb,2.5,0.83,'With four tasks and three people, one person gets two tasks and the others one each. Choose the pair of tasks that go together: C(4, 2) = 6 ways; then hand the three bundles -- the pair and the two single tasks -- to the three volunteers: 3! = 6 ways. In all, 6 × 6 = 36. (Or: 3⁴ = 81 ways in all, less 3 × 2⁴ = 48 that leave a chosen volunteer out, plus the 3 that were taken away twice: 81 - 48 + 3 = 36.) 81 lets a volunteer get nothing; 33 = 81 - 48 forgets to add back the 3 cases in which two volunteers are left out; 24 = 4 × 3 × 2 gives out only three of the tasks.','चार काम और तीन लोग हों तो एक को दो काम मिलते हैं और बाक़ी दोनों को एक-एक। साथ जाने वाले कामों की जोड़ी चुनें: C(4, 2) = 6 प्रकार; फिर तीन गठरियाँ -- जोड़ी और दो अकेले काम -- तीन स्वयंसेवकों को दें: 3! = 6 प्रकार। कुल 6 × 6 = 36। (या: कुल 3⁴ = 81 प्रकार, उनमें से 3 × 2⁴ = 48 घटाएँ जिनमें कोई चुना हुआ स्वयंसेवक छूटता है, और वे 3 जोड़ें जो दो बार घट गए: 81 - 48 + 3 = 36।) 81 किसी स्वयंसेवक को ख़ाली हाथ रहने देता है; 33 = 81 - 48 उन 3 मामलों को वापस जोड़ना भूल जाता है जिनमें दो स्वयंसेवक छूटते हैं; 24 = 4 × 3 × 2 केवल तीन काम बाँटता है।','csat-l4-s08-qa-pc-four-tasks-among-three-volunteers','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Puzzle Hybrid','mcq','medium','A worker is to be paid one-seventh of a silver bar at the end of each day for 7 days. The bar is marked into 7 equal parts, and pieces already paid may be taken back as change. What is the least number of cuts needed so that the worker can be paid exactly at the end of every day?','एक श्रमिक को 7 दिनों तक हर दिन के अंत में चाँदी की एक छड़ का सातवाँ भाग दिया जाना है। छड़ पर 7 बराबर भाग अंकित हैं, और पहले दिए टुकड़े छुट्टे के रूप में वापस लिए जा सकते हैं। कम से कम कितने कट चाहिए ताकि श्रमिक को हर दिन के अंत में ठीक भुगतान हो सके?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s08", "csat_order": 18}'::jsonb,'[{"id": "a", "body": "1", "body_hi": "1", "isCorrect": false}, {"id": "b", "body": "2", "body_hi": "2", "isCorrect": true}, {"id": "c", "body": "3", "body_hi": "3", "isCorrect": false}, {"id": "d", "body": "6", "body_hi": "6", "isCorrect": false}]'::jsonb,2.5,0.83,'Two cuts make pieces of 1, 2 and 4 parts, and every total from 1 to 7 is a sum of some of them. Day 1: give the 1. Day 2: give the 2 and take back the 1. Day 3: give the 1. Day 4: give the 4 and take back the 1 and the 2. Days 5 to 7 repeat the first three on top of the 4. One cut gives only two pieces, which can make at most three different totals, not seven; 3 cuts and 6 cuts work but are more than needed.','दो कट 1, 2 और 4 भागों के टुकड़े बनाते हैं, और 1 से 7 तक हर योग इनमें से कुछ का जोड़ है। दिन 1: 1 दें। दिन 2: 2 दें और 1 वापस लें। दिन 3: 1 दें। दिन 4: 4 दें और 1 तथा 2 वापस लें। दिन 5 से 7, 4 के ऊपर पहले तीन दिन दोहराते हैं। एक कट से केवल दो टुकड़े बनते हैं, जिनसे अधिक से अधिक तीन अलग योग बनते हैं, सात नहीं; 3 और 6 कट भी चलते हैं पर आवश्यकता से अधिक हैं।','csat-l4-s08-qa-ph-a-silver-bar-cut-to-pay-a-worker-daily','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Sequences & Series','mcq','hard','What is the value of 1 × 1! + 2 × 2! + 3 × 3! + ... + 9 × 9!? (Here n! = 1 × 2 × 3 × ... × n, and 10! = 36,28,800.)','1 × 1! + 2 × 2! + 3 × 3! + ... + 9 × 9! का मान क्या है? (यहाँ n! = 1 × 2 × 3 × ... × n, और 10! = 36,28,800।)','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s08", "csat_order": 19}'::jsonb,'[{"id": "a", "body": "3,62,879", "body_hi": "3,62,879", "isCorrect": false}, {"id": "b", "body": "32,65,920", "body_hi": "32,65,920", "isCorrect": false}, {"id": "c", "body": "36,28,799", "body_hi": "36,28,799", "isCorrect": true}, {"id": "d", "body": "36,28,800", "body_hi": "36,28,800", "isCorrect": false}]'::jsonb,2.5,0.83,'Each term can be rewritten: k × k! = (k + 1) × k! - k! = (k + 1)! - k!. So the sum is (2! - 1!) + (3! - 2!) + ... + (10! - 9!), and everything cancels except 10! - 1! = 36,28,800 - 1 = 36,28,799. (Check with a short case: 1 × 1! + 2 × 2! = 5 = 3! - 1.) 36,28,800 forgets to subtract 1!; 32,65,920 is the last term, 9 × 9!, alone; 3,62,879 = 9! - 1 stops the pattern a step too early.','हर पद को ऐसे लिखा जा सकता है: k × k! = (k + 1) × k! - k! = (k + 1)! - k!। इसलिए योग (2! - 1!) + (3! - 2!) + ... + (10! - 9!) है, और 10! - 1! = 36,28,800 - 1 = 36,28,799 के सिवा सब कट जाता है। (छोटे उदाहरण से जाँचें: 1 × 1! + 2 × 2! = 5 = 3! - 1।) 36,28,800, 1! घटाना भूल जाता है; 32,65,920 केवल अंतिम पद, 9 × 9!, है; 3,62,879 = 9! - 1 पैटर्न को एक क़दम पहले रोक देता है।','csat-l4-s08-qa-ss-k-times-k-factorial-added','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In May 1747, on board the British naval ship Salisbury, the surgeon James Lind took twelve sailors who were ill with scurvy and divided them into six pairs. All twelve were given the same diet, but each pair also received a different remedy: cider, a dilute acid, vinegar, sea water, a medicinal paste, or two oranges and a lemon a day. Within about a week one of the sailors given the fruit was fit for duty, and the other was well enough to help nurse the rest. No other pair did nearly as well. Lind''s trial is often called one of the first controlled experiments in medicine, because by treating similar patients alike in every way but one, he could see which remedy made the difference. Yet it changed little at first. Lind himself was not sure that the fruit was the cure, and later favoured a juice concentrated by boiling. The Royal Navy began issuing lemon juice to its sailors only in 1795, nearly fifty years after the trial.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
मई 1747 में ब्रिटिश नौसैनिक जहाज़ सैलिसबरी पर सर्जन जेम्स लिंड ने स्कर्वी से पीड़ित बारह नाविकों को लेकर छह जोड़ियों में बाँटा। सभी बारह को एक जैसा भोजन दिया गया, पर हर जोड़ी को एक अलग उपचार भी मिला: साइडर, एक तनु अम्ल, सिरका, समुद्री पानी, एक औषधीय लेप, या प्रतिदिन दो संतरे और एक नींबू। लगभग एक सप्ताह में फल पाने वाले नाविकों में से एक काम पर लौटने योग्य हो गया, और दूसरा इतना ठीक हो गया कि बाक़ियों की देखभाल में हाथ बँटा सके। कोई और जोड़ी इसके आसपास भी नहीं पहुँची। लिंड के परीक्षण को प्रायः चिकित्सा के पहले नियंत्रित प्रयोगों में गिना जाता है, क्योंकि एक जैसे रोगियों से एक बात छोड़कर हर तरह से एक जैसा व्यवहार करके वह देख सका कि अंतर किस उपचार से आया। फिर भी शुरू में इससे बहुत कम बदला। स्वयं लिंड को पक्का विश्वास नहीं था कि फल ही उपचार है, और बाद में उसने उबालकर गाढ़े किए गए रस को अधिक पसंद किया। ब्रिटिश नौसेना ने अपने नाविकों को नींबू का रस देना 1795 में ही शुरू किया, परीक्षण के लगभग पचास वर्ष बाद।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s08", "passage_group": "csat-l4-s08-p03", "csat_order": 20}'::jsonb,'[{"id": "a", "body": "Scurvy was cured in 1747 by a remedy that the Royal Navy then adopted at once for all its sailors.", "body_hi": "स्कर्वी का 1747 में एक ऐसे उपचार से इलाज हुआ जिसे ब्रिटिश नौसेना ने तुरंत अपने सभी नाविकों के लिए अपना लिया।", "isCorrect": false}, {"id": "b", "body": "Lind''s trial was badly flawed, because it used far too few sailors to show anything at all.", "body_hi": "लिंड का परीक्षण बहुत दोषपूर्ण था, क्योंकि उसमें कुछ भी दिखाने के लिए बहुत कम नाविक थे।", "isCorrect": false}, {"id": "c", "body": "A well-designed comparison pointed to a cure, yet the finding was slow to be acted upon.", "body_hi": "एक सुविचारित तुलना ने उपचार की ओर संकेत किया, फिर भी उस निष्कर्ष को समझने और अपनाने में देर लगी।", "isCorrect": true}, {"id": "d", "body": "Sea water and vinegar were found to work against scurvy as well as oranges and lemons did.", "body_hi": "समुद्री पानी और सिरका स्कर्वी के विरुद्ध संतरों और नींबुओं जितने ही असरदार पाए गए।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage describes a carefully designed comparison that pointed to a cure, then shows how slowly the finding was understood and acted upon -- even by Lind himself. The navy acted nearly fifty years later, not at once; the passage praises the design of the trial rather than calling it flawed; and it reports that no other pair did nearly as well as the pair given fruit.','परिच्छेद एक सावधानी से बनाई गई तुलना का वर्णन करता है जिसने उपचार की ओर संकेत किया, फिर दिखाता है कि उस निष्कर्ष को समझने और उस पर अमल करने में कितनी देर लगी -- स्वयं लिंड को भी। नौसेना ने लगभग पचास वर्ष बाद क़दम उठाया, तुरंत नहीं; परिच्छेद परीक्षण की बनावट को दोषपूर्ण नहीं, सराहनीय बताता है; और वह बताता है कि कोई और जोड़ी फल पाने वाली जोड़ी के आसपास भी नहीं पहुँची।','csat-l4-s08-rc-p03-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In May 1747, on board the British naval ship Salisbury, the surgeon James Lind took twelve sailors who were ill with scurvy and divided them into six pairs. All twelve were given the same diet, but each pair also received a different remedy: cider, a dilute acid, vinegar, sea water, a medicinal paste, or two oranges and a lemon a day. Within about a week one of the sailors given the fruit was fit for duty, and the other was well enough to help nurse the rest. No other pair did nearly as well. Lind''s trial is often called one of the first controlled experiments in medicine, because by treating similar patients alike in every way but one, he could see which remedy made the difference. Yet it changed little at first. Lind himself was not sure that the fruit was the cure, and later favoured a juice concentrated by boiling. The Royal Navy began issuing lemon juice to its sailors only in 1795, nearly fifty years after the trial.

Why, on the passage''s account, did Lind give all twelve sailors the same diet?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
मई 1747 में ब्रिटिश नौसैनिक जहाज़ सैलिसबरी पर सर्जन जेम्स लिंड ने स्कर्वी से पीड़ित बारह नाविकों को लेकर छह जोड़ियों में बाँटा। सभी बारह को एक जैसा भोजन दिया गया, पर हर जोड़ी को एक अलग उपचार भी मिला: साइडर, एक तनु अम्ल, सिरका, समुद्री पानी, एक औषधीय लेप, या प्रतिदिन दो संतरे और एक नींबू। लगभग एक सप्ताह में फल पाने वाले नाविकों में से एक काम पर लौटने योग्य हो गया, और दूसरा इतना ठीक हो गया कि बाक़ियों की देखभाल में हाथ बँटा सके। कोई और जोड़ी इसके आसपास भी नहीं पहुँची। लिंड के परीक्षण को प्रायः चिकित्सा के पहले नियंत्रित प्रयोगों में गिना जाता है, क्योंकि एक जैसे रोगियों से एक बात छोड़कर हर तरह से एक जैसा व्यवहार करके वह देख सका कि अंतर किस उपचार से आया। फिर भी शुरू में इससे बहुत कम बदला। स्वयं लिंड को पक्का विश्वास नहीं था कि फल ही उपचार है, और बाद में उसने उबालकर गाढ़े किए गए रस को अधिक पसंद किया। ब्रिटिश नौसेना ने अपने नाविकों को नींबू का रस देना 1795 में ही शुरू किया, परीक्षण के लगभग पचास वर्ष बाद।

परिच्छेद के अनुसार, लिंड ने सभी बारह नाविकों को एक जैसा भोजन क्यों दिया?','{"craft": "inference", "csat_set": "csat-l4-s08", "passage_group": "csat-l4-s08-p03", "csat_order": 21}'::jsonb,'[{"id": "a", "body": "So that any difference in recovery could be put down to the remedies alone.", "body_hi": "ताकि ठीक होने में कोई भी अंतर केवल उपचारों के कारण माना जा सके।", "isCorrect": true}, {"id": "b", "body": "Because the ship carried enough stores for only a single kind of diet.", "body_hi": "क्योंकि जहाज़ पर केवल एक ही प्रकार के भोजन लायक़ भंडार था।", "isCorrect": false}, {"id": "c", "body": "So that none of the sailors would know which remedy they had been given.", "body_hi": "ताकि किसी भी नाविक को पता न चले कि उसे कौन-सा उपचार मिला है।", "isCorrect": false}, {"id": "d", "body": "Because the navy''s rules did not allow any change in a sailor''s daily food.", "body_hi": "क्योंकि नौसेना के नियम नाविक के दैनिक भोजन में कोई बदलाव नहीं होने देते थे।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage says that by treating similar patients alike in every way but one, Lind could see which remedy made the difference. A common diet keeps food from being a second difference between the pairs, so any difference in recovery can be put down to the remedies. The passage says nothing of the ship''s stores or the navy''s rules about food, and the sailors could hardly have been kept from knowing whether they were eating oranges or drinking sea water.','परिच्छेद कहता है कि एक जैसे रोगियों से एक बात छोड़कर हर तरह से एक जैसा व्यवहार करके लिंड देख सका कि अंतर किस उपचार से आया। एक जैसा भोजन यह सुनिश्चित करता है कि जोड़ियों के बीच भोजन दूसरा अंतर न बने, ताकि ठीक होने में कोई भी अंतर उपचारों के कारण माना जा सके। परिच्छेद जहाज़ के भंडार या भोजन के बारे में नौसेना के नियमों पर कुछ नहीं कहता, और नाविकों से यह छिपाना शायद ही संभव था कि वे संतरे खा रहे हैं या समुद्री पानी पी रहे हैं।','csat-l4-s08-rc-p03-why-one-diet-for-all','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In May 1747, on board the British naval ship Salisbury, the surgeon James Lind took twelve sailors who were ill with scurvy and divided them into six pairs. All twelve were given the same diet, but each pair also received a different remedy: cider, a dilute acid, vinegar, sea water, a medicinal paste, or two oranges and a lemon a day. Within about a week one of the sailors given the fruit was fit for duty, and the other was well enough to help nurse the rest. No other pair did nearly as well. Lind''s trial is often called one of the first controlled experiments in medicine, because by treating similar patients alike in every way but one, he could see which remedy made the difference. Yet it changed little at first. Lind himself was not sure that the fruit was the cure, and later favoured a juice concentrated by boiling. The Royal Navy began issuing lemon juice to its sailors only in 1795, nearly fifty years after the trial.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
मई 1747 में ब्रिटिश नौसैनिक जहाज़ सैलिसबरी पर सर्जन जेम्स लिंड ने स्कर्वी से पीड़ित बारह नाविकों को लेकर छह जोड़ियों में बाँटा। सभी बारह को एक जैसा भोजन दिया गया, पर हर जोड़ी को एक अलग उपचार भी मिला: साइडर, एक तनु अम्ल, सिरका, समुद्री पानी, एक औषधीय लेप, या प्रतिदिन दो संतरे और एक नींबू। लगभग एक सप्ताह में फल पाने वाले नाविकों में से एक काम पर लौटने योग्य हो गया, और दूसरा इतना ठीक हो गया कि बाक़ियों की देखभाल में हाथ बँटा सके। कोई और जोड़ी इसके आसपास भी नहीं पहुँची। लिंड के परीक्षण को प्रायः चिकित्सा के पहले नियंत्रित प्रयोगों में गिना जाता है, क्योंकि एक जैसे रोगियों से एक बात छोड़कर हर तरह से एक जैसा व्यवहार करके वह देख सका कि अंतर किस उपचार से आया। फिर भी शुरू में इससे बहुत कम बदला। स्वयं लिंड को पक्का विश्वास नहीं था कि फल ही उपचार है, और बाद में उसने उबालकर गाढ़े किए गए रस को अधिक पसंद किया। ब्रिटिश नौसेना ने अपने नाविकों को नींबू का रस देना 1795 में ही शुरू किया, परीक्षण के लगभग पचास वर्ष बाद।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["The trial shows that oranges and lemons cure scurvy in every patient who takes them.", "A clear result from a well-designed trial does not by itself ensure that the result is acted upon."], "statements_hi": ["परीक्षण दिखाता है कि संतरे और नींबू उन्हें लेने वाले हर रोगी की स्कर्वी ठीक कर देते हैं।", "सुविचारित परीक्षण का स्पष्ट परिणाम अपने आप यह सुनिश्चित नहीं करता कि उस पर अमल होगा।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s08", "passage_group": "csat-l4-s08-p03", "csat_order": 22}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Only 2 is valid. The trial pointed clearly to the fruit, yet Lind was unsure, preferred a boiled juice, and the navy waited nearly fifty years: a clear result did not by itself ensure that it was acted upon. 1 claims far more than the trial showed: two sailors took the fruit, one became fit for duty and the other improved -- that is not evidence that the fruit cures every patient.','केवल 2 वैध है। परीक्षण ने स्पष्ट रूप से फल की ओर संकेत किया, फिर भी लिंड अनिश्चित रहा, उसने उबला रस पसंद किया, और नौसेना ने लगभग पचास वर्ष प्रतीक्षा की: स्पष्ट परिणाम अपने आप उस पर अमल सुनिश्चित नहीं करता। 1 परीक्षण के दिखाए से कहीं अधिक दावा करता है: दो नाविकों ने फल लिया, एक काम योग्य हुआ और दूसरे में सुधार हुआ -- यह इसका प्रमाण नहीं कि फल हर रोगी को ठीक कर देता है।','csat-l4-s08-rc-p03-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Logical Reasoning','Blood Relation','mcq','hard','Pointing to a boy, Neha says, ''He is the son of a daughter of the father of my maternal uncle.'' How is the boy related to Neha?','एक लड़के की ओर इशारा करते हुए नेहा कहती है, ''वह मेरे मामा के पिता की एक बेटी का बेटा है।'' वह लड़का नेहा का क्या लगता है?','{"craft": "inference", "csat_set": "csat-l4-s08", "csat_order": 23}'::jsonb,'[{"id": "a", "body": "Brother or cousin", "body_hi": "भाई या मौसेरा भाई", "isCorrect": true}, {"id": "b", "body": "Brother only", "body_hi": "केवल भाई", "isCorrect": false}, {"id": "c", "body": "Cousin only, through her mother''s sister", "body_hi": "केवल मौसेरा भाई, उसकी मौसी के द्वारा", "isCorrect": false}, {"id": "d", "body": "Nephew", "body_hi": "भतीजा या भांजा", "isCorrect": false}]'::jsonb,2.5,0.83,'The father of Neha''s maternal uncle is her mother''s father. A daughter of his is either Neha''s mother herself or one of her mother''s sisters, and the words do not say which. The boy is that daughter''s son: Neha''s brother if the daughter is her mother, her cousin if the daughter is her aunt. ''Brother only'' and ''cousin only'' each pick one reading without warrant; a nephew would be the son of Neha''s own brother or sister.','नेहा के मामा के पिता उसकी माँ के पिता (नाना) हैं। उनकी बेटी या तो स्वयं नेहा की माँ है या उसकी माँ की कोई बहन (मौसी), और शब्द यह नहीं बताते कि कौन। लड़का उसी बेटी का बेटा है: बेटी माँ हो तो नेहा का भाई, मौसी हो तो मौसेरा भाई। ''केवल भाई'' और ''केवल मौसेरा भाई'' बिना आधार के एक अर्थ चुन लेते हैं; भतीजा या भांजा नेहा के अपने भाई या बहन का बेटा होता।','csat-l4-s08-lr-br-the-son-of-a-daughter-of-a-maternal-grandfather','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Ratio, Mixtures & Alligation','mcq','easy','2 litres of water at 80 °C are mixed with 3 litres of water at 20 °C. If no heat is lost, what is the temperature of the mixture?','80 °C के 2 लीटर पानी को 20 °C के 3 लीटर पानी में मिलाया जाता है। यदि कोई ऊष्मा नष्ट न हो, तो मिश्रण का तापमान क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s08", "csat_order": 24}'::jsonb,'[{"id": "a", "body": "44 °C", "body_hi": "44 °C", "isCorrect": true}, {"id": "b", "body": "50 °C", "body_hi": "50 °C", "isCorrect": false}, {"id": "c", "body": "53 °C", "body_hi": "53 °C", "isCorrect": false}, {"id": "d", "body": "56 °C", "body_hi": "56 °C", "isCorrect": false}]'::jsonb,2.5,0.83,'The mixture''s temperature is the average weighted by the amounts: (2 × 80 + 3 × 20) ÷ 5 = 220 ÷ 5 = 44 °C -- nearer 20 °C, because there is more of the cold water. 50 °C is the plain average, which would need equal amounts; 56 °C puts the weights the wrong way round, (3 × 80 + 2 × 20) ÷ 5; 53 °C has no basis.','मिश्रण का तापमान मात्राओं से भारित औसत है: (2 × 80 + 3 × 20) ÷ 5 = 220 ÷ 5 = 44 °C -- 20 °C के अधिक निकट, क्योंकि ठंडा पानी अधिक है। 50 °C साधारण औसत है, जिसके लिए मात्राएँ बराबर होनी चाहिए; 56 °C भार उलट देता है, (3 × 80 + 2 × 20) ÷ 5; 53 °C का कोई आधार नहीं।','csat-l4-s08-qa-rm-water-mixed-at-two-temperatures','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Number Theory','statement_based','hard','Consider every right-angled triangle whose three sides are whole numbers, such as 3, 4, 5 or 5, 12, 13. Which of the following statements is/are true of every such triangle?','हर ऐसे समकोण त्रिभुज पर विचार कीजिए जिसकी तीनों भुजाएँ पूर्ण संख्याएँ हैं, जैसे 3, 4, 5 या 5, 12, 13। निम्नलिखित में से कौन-सा/से कथन हर ऐसे त्रिभुज के लिए सत्य है/हैं?','{"statements": ["At least one of its three sides is a multiple of 5.", "Its area is a whole number that is a multiple of 6."], "statements_hi": ["उसकी तीनों भुजाओं में से कम से कम एक 5 की गुणज है।", "उसका क्षेत्रफल एक पूर्ण संख्या है जो 6 की गुणज है।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s08", "csat_order": 25}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Both are true. 1: a square leaves remainder 0, 1 or 4 when divided by 5. If neither shorter side were a multiple of 5, their squares would add to something leaving 2, 3 or 0; 2 and 3 are impossible for the square of the longest side, and 0 makes the longest side a multiple of 5. So some side always is (3, 4, 5; 20, 21, 29; 8, 15, 17 through 15). 2: one of the two shorter sides is always a multiple of 3 and one a multiple of 4, so their product is a multiple of 12 and the area, half that product, a multiple of 6: 3, 4, 5 gives 6; 5, 12, 13 gives 30; 8, 15, 17 gives 60.','दोनों सत्य हैं। 1: किसी वर्ग को 5 से भाग देने पर शेष 0, 1 या 4 बचता है। यदि दोनों छोटी भुजाओं में से कोई 5 की गुणज न हो, तो उनके वर्गों के योग का शेष 2, 3 या 0 होगा; सबसे लंबी भुजा के वर्ग के लिए 2 और 3 असंभव हैं, और 0 का अर्थ है कि सबसे लंबी भुजा 5 की गुणज है। अतः कोई न कोई भुजा सदा 5 की गुणज होती है (3, 4, 5; 20, 21, 29; 8, 15, 17 में 15)। 2: दोनों छोटी भुजाओं में से एक सदा 3 की गुणज और एक 4 की गुणज होती है, इसलिए उनका गुणनफल 12 का गुणज है और क्षेत्रफल, उस गुणनफल का आधा, 6 का गुणज: 3, 4, 5 से 6; 5, 12, 13 से 30; 8, 15, 17 से 60।','csat-l4-s08-qa-nt-what-every-whole-number-right-triangle-shares','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Statement-Conclusion/Assumption','mcq','medium','''The health minister tells us to give up sugary drinks, yet the minister drinks three colas a day. So the advice can safely be ignored.'' Which one of the following best describes the flaw in this argument?','''स्वास्थ्य मंत्री हमें मीठे पेय छोड़ने को कहते हैं, फिर भी मंत्री स्वयं दिन में तीन कोला पीते हैं। इसलिए इस सलाह की बेझिझक अनदेखी की जा सकती है।'' निम्नलिखित में से कौन-सा इस तर्क की त्रुटि का सबसे अच्छा वर्णन करता है?','{"craft": "inference", "csat_set": "csat-l4-s08", "csat_order": 26}'::jsonb,'[{"id": "a", "body": "It assumes that a health minister must know more about health than any of the people being advised.", "body_hi": "यह मान लेता है कि स्वास्थ्य मंत्री को स्वास्थ्य के बारे में सलाह पाने वाले हर व्यक्ति से अधिक जानकारी होनी चाहिए।", "isCorrect": false}, {"id": "b", "body": "It generalises from the habits of a single minister to the habits of everyone who holds public office.", "body_hi": "यह एक मंत्री की आदतों से सार्वजनिक पद पर बैठे हर व्यक्ति की आदतों के बारे में सामान्य निष्कर्ष निकालता है।", "isCorrect": false}, {"id": "c", "body": "It treats the minister''s fondness for colas as the cause of the advice that the minister has given.", "body_hi": "यह मंत्री के कोला-प्रेम को मंत्री द्वारा दी गई सलाह का कारण मान लेता है।", "isCorrect": false}, {"id": "d", "body": "It rejects the advice because of the adviser''s habits, which do not show whether the advice is sound.", "body_hi": "यह सलाह को सलाहकार की अपनी आदतों के कारण ठुकराता है, जिनसे यह पता नहीं चलता कि सलाह ठीक है या नहीं।", "isCorrect": true}]'::jsonb,2.5,0.83,'Whether sugary drinks are harmful depends on the evidence about sugary drinks, not on whether the person giving the advice follows it. A hypocrite can give sound advice. The argument makes no claim about how much the minister knows; it draws no conclusion about other office-holders; and it does not say the cola habit caused the advice.','मीठे पेय हानिकारक हैं या नहीं, यह मीठे पेयों के बारे में प्रमाण पर निर्भर है, इस पर नहीं कि सलाह देने वाला स्वयं उसका पालन करता है या नहीं। पाखंडी भी ठीक सलाह दे सकता है। तर्क मंत्री की जानकारी के बारे में कोई दावा नहीं करता; वह दूसरे पदधारियों के बारे में कोई निष्कर्ष नहीं निकालता; और वह यह नहीं कहता कि कोला की आदत सलाह का कारण बनी।','csat-l4-s08-lr-sc-advice-dismissed-because-of-the-adviser-s-habit','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Article 21 of the Constitution says that no person shall be deprived of life or personal liberty ''except according to procedure established by law''. The Constituent Assembly chose these words, taken from the Constitution of Japan, in place of the American phrase ''due process of law'', partly to keep judges from striking down laws merely because they thought them unwise. In the Gopalan case of 1950 the Supreme Court read the article in that spirit: if a law laid down a procedure and the procedure was followed, Article 21 was satisfied, and each fundamental right was to be read on its own. In 1978, in the Maneka Gandhi case, in which a passport had been impounded without reasons being given or a hearing held, the Court changed course. It held that the procedure must itself be fair, just and reasonable, not arbitrary, and that Articles 14, 19 and 21 must be read together. Supporters see this as giving life to rights that a legislature could otherwise take away by any procedure it chose. Critics reply that the Court thereby brought back, through interpretation, much of the due process that the Assembly had deliberately left out.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
संविधान का अनुच्छेद 21 कहता है कि किसी व्यक्ति को उसके प्राण या दैहिक स्वतंत्रता से ''विधि द्वारा स्थापित प्रक्रिया के अनुसार ही'' वंचित किया जाएगा, अन्यथा नहीं। संविधान सभा ने ये शब्द, जो जापान के संविधान से लिए गए, अमेरिकी पद ''विधि की सम्यक प्रक्रिया'' (ड्यू प्रोसेस) के स्थान पर चुने, आंशिक रूप से इसलिए कि न्यायाधीश क़ानूनों को केवल इस कारण रद्द न करें कि वे उन्हें अविवेकपूर्ण लगते हैं। 1950 के गोपालन मामले में सर्वोच्च न्यायालय ने अनुच्छेद को इसी भावना से पढ़ा: यदि किसी क़ानून ने प्रक्रिया निर्धारित की और उसका पालन हुआ, तो अनुच्छेद 21 संतुष्ट था, और हर मौलिक अधिकार को अलग से पढ़ा जाना था। 1978 में मेनका गांधी मामले में, जिसमें बिना कारण बताए या सुनवाई किए एक पासपोर्ट ज़ब्त कर लिया गया था, न्यायालय ने अपनी दिशा बदली। उसने माना कि प्रक्रिया स्वयं उचित, न्यायपूर्ण और युक्तियुक्त होनी चाहिए, मनमानी नहीं, और अनुच्छेद 14, 19 और 21 को साथ पढ़ा जाना चाहिए। समर्थक इसे उन अधिकारों में जान डालने वाला मानते हैं जिन्हें अन्यथा विधायिका अपनी चुनी किसी भी प्रक्रिया से छीन सकती थी। आलोचक उत्तर देते हैं कि इस तरह न्यायालय ने व्याख्या के रास्ते उस सम्यक प्रक्रिया का बड़ा भाग वापस ला दिया जिसे सभा ने जान-बूझकर छोड़ा था।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s08", "passage_group": "csat-l4-s08-p04", "csat_order": 27}'::jsonb,'[{"id": "a", "body": "India''s fundamental rights were copied, almost word for word, from the Constitution of Japan.", "body_hi": "भारत के मौलिक अधिकार लगभग शब्दशः जापान के संविधान से लिए गए थे।", "isCorrect": false}, {"id": "b", "body": "Since 1978 Parliament has been unable to make any law at all that restricts personal liberty.", "body_hi": "1978 से संसद दैहिक स्वतंत्रता पर किसी भी प्रकार की रोक लगाने वाला कोई क़ानून नहीं बना सकी है।", "isCorrect": false}, {"id": "c", "body": "The Gopalan case was rightly decided, and the Maneka Gandhi case was decided wrongly.", "body_hi": "गोपालन मामले का निर्णय सही था, और मेनका गांधी मामले का निर्णय ग़लत।", "isCorrect": false}, {"id": "d", "body": "The Court read Article 21 more widely than its words, which some welcome and others question.", "body_hi": "न्यायालय ने अनुच्छेद 21 को उसके शब्दों से व्यापक पढ़ा, जिस पर मत बँटे हुए हैं।", "isCorrect": true}]'::jsonb,2.5,0.83,'The passage traces how the Supreme Court moved from a narrow reading of Article 21 to one that tests whether a procedure is fair, and sets out the case for and against that change. It says only the phrase in Article 21 came from Japan, not the fundamental rights as a whole; it says nothing about Parliament being unable to restrict liberty -- a fair procedure can still do so; and it reports both views without declaring either judgment wrong.','परिच्छेद बताता है कि सर्वोच्च न्यायालय अनुच्छेद 21 की संकीर्ण व्याख्या से ऐसी व्याख्या तक कैसे पहुँचा जो जाँचती है कि प्रक्रिया उचित है या नहीं, और उस बदलाव के पक्ष और विपक्ष के तर्क रखता है। वह कहता है कि केवल अनुच्छेद 21 का पद जापान से आया, पूरे मौलिक अधिकार नहीं; वह यह नहीं कहता कि संसद स्वतंत्रता पर कोई रोक नहीं लगा सकती -- उचित प्रक्रिया से अब भी लगा सकती है; और वह दोनों मत रखता है, किसी निर्णय को ग़लत घोषित किए बिना।','csat-l4-s08-rc-p04-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Article 21 of the Constitution says that no person shall be deprived of life or personal liberty ''except according to procedure established by law''. The Constituent Assembly chose these words, taken from the Constitution of Japan, in place of the American phrase ''due process of law'', partly to keep judges from striking down laws merely because they thought them unwise. In the Gopalan case of 1950 the Supreme Court read the article in that spirit: if a law laid down a procedure and the procedure was followed, Article 21 was satisfied, and each fundamental right was to be read on its own. In 1978, in the Maneka Gandhi case, in which a passport had been impounded without reasons being given or a hearing held, the Court changed course. It held that the procedure must itself be fair, just and reasonable, not arbitrary, and that Articles 14, 19 and 21 must be read together. Supporters see this as giving life to rights that a legislature could otherwise take away by any procedure it chose. Critics reply that the Court thereby brought back, through interpretation, much of the due process that the Assembly had deliberately left out.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
संविधान का अनुच्छेद 21 कहता है कि किसी व्यक्ति को उसके प्राण या दैहिक स्वतंत्रता से ''विधि द्वारा स्थापित प्रक्रिया के अनुसार ही'' वंचित किया जाएगा, अन्यथा नहीं। संविधान सभा ने ये शब्द, जो जापान के संविधान से लिए गए, अमेरिकी पद ''विधि की सम्यक प्रक्रिया'' (ड्यू प्रोसेस) के स्थान पर चुने, आंशिक रूप से इसलिए कि न्यायाधीश क़ानूनों को केवल इस कारण रद्द न करें कि वे उन्हें अविवेकपूर्ण लगते हैं। 1950 के गोपालन मामले में सर्वोच्च न्यायालय ने अनुच्छेद को इसी भावना से पढ़ा: यदि किसी क़ानून ने प्रक्रिया निर्धारित की और उसका पालन हुआ, तो अनुच्छेद 21 संतुष्ट था, और हर मौलिक अधिकार को अलग से पढ़ा जाना था। 1978 में मेनका गांधी मामले में, जिसमें बिना कारण बताए या सुनवाई किए एक पासपोर्ट ज़ब्त कर लिया गया था, न्यायालय ने अपनी दिशा बदली। उसने माना कि प्रक्रिया स्वयं उचित, न्यायपूर्ण और युक्तियुक्त होनी चाहिए, मनमानी नहीं, और अनुच्छेद 14, 19 और 21 को साथ पढ़ा जाना चाहिए। समर्थक इसे उन अधिकारों में जान डालने वाला मानते हैं जिन्हें अन्यथा विधायिका अपनी चुनी किसी भी प्रक्रिया से छीन सकती थी। आलोचक उत्तर देते हैं कि इस तरह न्यायालय ने व्याख्या के रास्ते उस सम्यक प्रक्रिया का बड़ा भाग वापस ला दिया जिसे सभा ने जान-बूझकर छोड़ा था।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["Under the Gopalan reading, a law that laid down an unfair procedure could still satisfy Article 21.", "The critics'' objection is that the Maneka Gandhi judgment protects too little personal liberty."], "statements_hi": ["गोपालन व्याख्या में, अनुचित प्रक्रिया निर्धारित करने वाला क़ानून भी अनुच्छेद 21 को संतुष्ट कर सकता था।", "आलोचकों की आपत्ति यह है कि मेनका गांधी निर्णय दैहिक स्वतंत्रता की बहुत कम रक्षा करता है।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s08", "passage_group": "csat-l4-s08-p04", "csat_order": 28}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Only 1 is valid. Under the Gopalan reading, Article 21 asked only whether a law laid down a procedure and whether it was followed; whether the procedure was fair did not enter into it, so an unfair procedure set by law could still satisfy the article. 2 reverses the critics'' complaint: they say the Court took on more power than the framers intended, not that the judgment protects too little liberty.','केवल 1 वैध है। गोपालन व्याख्या में अनुच्छेद 21 केवल यह पूछता था कि क्या किसी क़ानून ने प्रक्रिया निर्धारित की और क्या उसका पालन हुआ; प्रक्रिया उचित है या नहीं, यह प्रश्न ही नहीं था, इसलिए क़ानून द्वारा निर्धारित अनुचित प्रक्रिया भी अनुच्छेद को संतुष्ट कर सकती थी। 2 आलोचकों की शिकायत को उलट देता है: वे कहते हैं कि न्यायालय ने निर्माताओं के इरादे से अधिक शक्ति ले ली, यह नहीं कि निर्णय बहुत कम स्वतंत्रता की रक्षा करता है।','csat-l4-s08-rc-p04-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Specific Detail','mcq','easy','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Article 21 of the Constitution says that no person shall be deprived of life or personal liberty ''except according to procedure established by law''. The Constituent Assembly chose these words, taken from the Constitution of Japan, in place of the American phrase ''due process of law'', partly to keep judges from striking down laws merely because they thought them unwise. In the Gopalan case of 1950 the Supreme Court read the article in that spirit: if a law laid down a procedure and the procedure was followed, Article 21 was satisfied, and each fundamental right was to be read on its own. In 1978, in the Maneka Gandhi case, in which a passport had been impounded without reasons being given or a hearing held, the Court changed course. It held that the procedure must itself be fair, just and reasonable, not arbitrary, and that Articles 14, 19 and 21 must be read together. Supporters see this as giving life to rights that a legislature could otherwise take away by any procedure it chose. Critics reply that the Court thereby brought back, through interpretation, much of the due process that the Assembly had deliberately left out.

According to the passage, what had happened in the Maneka Gandhi case?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
संविधान का अनुच्छेद 21 कहता है कि किसी व्यक्ति को उसके प्राण या दैहिक स्वतंत्रता से ''विधि द्वारा स्थापित प्रक्रिया के अनुसार ही'' वंचित किया जाएगा, अन्यथा नहीं। संविधान सभा ने ये शब्द, जो जापान के संविधान से लिए गए, अमेरिकी पद ''विधि की सम्यक प्रक्रिया'' (ड्यू प्रोसेस) के स्थान पर चुने, आंशिक रूप से इसलिए कि न्यायाधीश क़ानूनों को केवल इस कारण रद्द न करें कि वे उन्हें अविवेकपूर्ण लगते हैं। 1950 के गोपालन मामले में सर्वोच्च न्यायालय ने अनुच्छेद को इसी भावना से पढ़ा: यदि किसी क़ानून ने प्रक्रिया निर्धारित की और उसका पालन हुआ, तो अनुच्छेद 21 संतुष्ट था, और हर मौलिक अधिकार को अलग से पढ़ा जाना था। 1978 में मेनका गांधी मामले में, जिसमें बिना कारण बताए या सुनवाई किए एक पासपोर्ट ज़ब्त कर लिया गया था, न्यायालय ने अपनी दिशा बदली। उसने माना कि प्रक्रिया स्वयं उचित, न्यायपूर्ण और युक्तियुक्त होनी चाहिए, मनमानी नहीं, और अनुच्छेद 14, 19 और 21 को साथ पढ़ा जाना चाहिए। समर्थक इसे उन अधिकारों में जान डालने वाला मानते हैं जिन्हें अन्यथा विधायिका अपनी चुनी किसी भी प्रक्रिया से छीन सकती थी। आलोचक उत्तर देते हैं कि इस तरह न्यायालय ने व्याख्या के रास्ते उस सम्यक प्रक्रिया का बड़ा भाग वापस ला दिया जिसे सभा ने जान-बूझकर छोड़ा था।

परिच्छेद के अनुसार, मेनका गांधी मामले में क्या हुआ था?','{"craft": "precision", "csat_set": "csat-l4-s08", "passage_group": "csat-l4-s08-p04", "csat_order": 29}'::jsonb,'[{"id": "a", "body": "A person was arrested under a law passed soon after the Gopalan case.", "body_hi": "गोपालन मामले के तुरंत बाद बने एक क़ानून के तहत एक व्यक्ति को गिरफ़्तार किया गया।", "isCorrect": false}, {"id": "b", "body": "A passport was impounded with no reasons given and no hearing held.", "body_hi": "बिना कारण बताए या सुनवाई किए एक पासपोर्ट ज़ब्त कर लिया गया।", "isCorrect": true}, {"id": "c", "body": "A candidate was barred from contesting an election to Parliament.", "body_hi": "एक उम्मीदवार को संसद का चुनाव लड़ने से रोक दिया गया।", "isCorrect": false}, {"id": "d", "body": "Private property was taken over by the State without any compensation.", "body_hi": "राज्य ने बिना किसी मुआवज़े के निजी संपत्ति ले ली।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage says that a passport had been impounded without reasons being given or a hearing held. It mentions no arrest, no election and no taking of property.','परिच्छेद कहता है कि बिना कारण बताए या सुनवाई किए एक पासपोर्ट ज़ब्त कर लिया गया था। वह किसी गिरफ़्तारी, चुनाव या संपत्ति लिए जाने का उल्लेख नहीं करता।','csat-l4-s08-rc-p04-what-happened-in-the-case','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Ratio, Mixtures & Alligation','mcq','medium','A town''s sex ratio is 940 -- that is, there are 940 females for every 1,000 males. If the town has 38,800 people, how many of them are female?','एक कस्बे का लिंगानुपात 940 है -- अर्थात हर 1,000 पुरुषों पर 940 महिलाएँ हैं। यदि कस्बे में 38,800 लोग हैं, तो उनमें कितनी महिलाएँ हैं?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s08", "csat_order": 30}'::jsonb,'[{"id": "a", "body": "18,236", "body_hi": "18,236", "isCorrect": false}, {"id": "b", "body": "18,800", "body_hi": "18,800", "isCorrect": true}, {"id": "c", "body": "19,400", "body_hi": "19,400", "isCorrect": false}, {"id": "d", "body": "20,000", "body_hi": "20,000", "isCorrect": false}]'::jsonb,2.5,0.83,'Out of every 1,000 + 940 = 1,940 people, 940 are female. 38,800 ÷ 1,940 = 20, so there are 20 × 940 = 18,800 females (and 20 × 1,000 = 20,000 males). 18,236 takes 940 out of 2,000, that is 47% of the people, as if the ratio were of females to twice the males; 19,400 is half the town, ignoring the ratio; 20,000 is the number of males.','हर 1,000 + 940 = 1,940 लोगों में 940 महिलाएँ हैं। 38,800 ÷ 1,940 = 20, इसलिए 20 × 940 = 18,800 महिलाएँ हैं (और 20 × 1,000 = 20,000 पुरुष)। 18,236, 2,000 में से 940, यानी लोगों का 47%, लेता है, मानो अनुपात महिलाओं का पुरुषों की दोगुनी संख्या से हो; 19,400 अनुपात की अनदेखी कर कस्बे का आधा है; 20,000 पुरुषों की संख्या है।','csat-l4-s08-qa-rm-a-sex-ratio-turned-into-a-count','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','easy','What is the value of 2026² - 2025 × 2027?','2026² - 2025 × 2027 का मान क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s08", "csat_order": 31}'::jsonb,'[{"id": "a", "body": "-1", "body_hi": "-1", "isCorrect": false}, {"id": "b", "body": "0", "body_hi": "0", "isCorrect": false}, {"id": "c", "body": "1", "body_hi": "1", "isCorrect": true}, {"id": "d", "body": "2", "body_hi": "2", "isCorrect": false}]'::jsonb,2.5,0.83,'2025 × 2027 = (2026 - 1)(2026 + 1) = 2026² - 1, so 2026² - 2025 × 2027 = 2026² - (2026² - 1) = 1, with no long multiplication. -1 subtracts the wrong way round; 0 assumes the two products are equal; 2 counts the 1 by which each factor differs from 2026 twice.','2025 × 2027 = (2026 - 1)(2026 + 1) = 2026² - 1, इसलिए 2026² - 2025 × 2027 = 2026² - (2026² - 1) = 1, बिना लंबे गुणा के। -1 उलटा घटाता है; 0 मान लेता है कि दोनों गुणनफल बराबर हैं; 2, हर गुणनखंड के 2026 से 1 के अंतर को दो बार गिनता है।','csat-l4-s08-qa-nt-2026-squared-less-2025-times-2027','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Seating Arrangement','mcq','medium','Five people stand in a queue in the order P, Q, R, S, T, with P at the front. Then, one after another: the person at the front is served and leaves; S moves two places forward; U joins at the back; and the person who is now second lets the person just behind go ahead. Who is now third in the queue?','पाँच लोग P, Q, R, S, T के क्रम में एक पंक्ति में खड़े हैं, P सबसे आगे है। फिर एक के बाद एक: सबसे आगे वाले का काम होता है और वह चला जाता है; S दो स्थान आगे बढ़ता है; U पीछे जुड़ता है; और जो अब दूसरे स्थान पर है, वह अपने ठीक पीछे वाले को आगे जाने देता है। अब पंक्ति में तीसरे स्थान पर कौन है?','{"craft": "inference", "csat_set": "csat-l4-s08", "csat_order": 32}'::jsonb,'[{"id": "a", "body": "R", "body_hi": "R", "isCorrect": false}, {"id": "b", "body": "Q", "body_hi": "Q", "isCorrect": true}, {"id": "c", "body": "S", "body_hi": "S", "isCorrect": false}, {"id": "d", "body": "T", "body_hi": "T", "isCorrect": false}]'::jsonb,2.5,0.83,'After P leaves the queue is Q, R, S, T. S moves two places forward, past R and Q: S, Q, R, T. U joins at the back: S, Q, R, T, U. Q, now second, lets R go ahead: S, R, Q, T, U. Q is third. R is third only if the last swap is forgotten; S, if S moves just one place forward; T, if the person served is not removed.','P के जाने के बाद पंक्ति Q, R, S, T है। S, R और Q को पार करके दो स्थान आगे बढ़ता है: S, Q, R, T। U पीछे जुड़ता है: S, Q, R, T, U। अब दूसरे स्थान पर Q, R को आगे जाने देता है: S, R, Q, T, U। Q तीसरे स्थान पर है। R तीसरा तभी होता जब अंतिम अदला-बदली भुला दी जाए; S, यदि S केवल एक स्थान आगे बढ़े; T, यदि जिसका काम हुआ उसे हटाया न जाए।','csat-l4-s08-lr-sa-a-queue-that-changes-four-times','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Speed-Distance-Time','mcq','hard','Asha and Bina must both reach a town 24 km away, and they have one bicycle between them. Asha walks at 4 km/h and cycles at 12 km/h; Bina walks at 6 km/h and cycles at 18 km/h. They set out together: Asha rides some distance, leaves the bicycle by the road and walks on, while Bina walks until she reaches the bicycle and then rides the rest of the way. If they arrive at the same moment, how long does the journey take?','आशा और बीना दोनों को 24 किमी दूर एक कस्बे तक पहुँचना है, और उनके पास एक ही साइकिल है। आशा 4 किमी/घंटा से चलती और 12 किमी/घंटा से साइकिल चलाती है; बीना 6 किमी/घंटा से चलती और 18 किमी/घंटा से साइकिल चलाती है। वे साथ निकलती हैं: आशा कुछ दूरी साइकिल से जाती है, साइकिल सड़क किनारे छोड़कर पैदल आगे बढ़ती है, जबकि बीना साइकिल तक पैदल पहुँचकर बाक़ी रास्ता साइकिल से तय करती है। यदि दोनों एक ही क्षण पहुँचती हैं, तो यात्रा में कितना समय लगता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s08", "csat_order": 33}'::jsonb,'[{"id": "a", "body": "2 h 40 min", "body_hi": "2 घंटे 40 मिनट", "isCorrect": false}, {"id": "b", "body": "3 h 12 min", "body_hi": "3 घंटे 12 मिनट", "isCorrect": true}, {"id": "c", "body": "3 h 20 min", "body_hi": "3 घंटे 20 मिनट", "isCorrect": false}, {"id": "d", "body": "4 h", "body_hi": "4 घंटे", "isCorrect": false}]'::jsonb,2.5,0.83,'Let Asha ride x km. Asha takes x/12 + (24 - x)/4 = 6 - x/6 hours; Bina takes x/6 + (24 - x)/18 = 4/3 + x/9 hours. Equal times: 6 - 4/3 = x/6 + x/9, so 14/3 = 5x/18 and x = 16.8 km. The journey takes 6 - 16.8/6 = 3.2 h = 3 h 12 min. (Bina reaches the bicycle after 16.8 ÷ 6 = 2.8 h; Asha left it there after 1.4 h, so it is waiting.) Leaving the bicycle half-way would not bring them in together: Asha would take 4 h and Bina 2 h 40 min, and 3 h 20 min is just the average of those two.','मान लें आशा x किमी साइकिल से जाती है। आशा को x/12 + (24 - x)/4 = 6 - x/6 घंटे लगते हैं; बीना को x/6 + (24 - x)/18 = 4/3 + x/9 घंटे। समय बराबर: 6 - 4/3 = x/6 + x/9, अतः 14/3 = 5x/18 और x = 16.8 किमी। यात्रा में 6 - 16.8/6 = 3.2 घंटे = 3 घंटे 12 मिनट लगते हैं। (बीना 16.8 ÷ 6 = 2.8 घंटे बाद साइकिल तक पहुँचती है; आशा उसे 1.4 घंटे बाद वहाँ छोड़ चुकी थी, इसलिए साइकिल वहीं है।) साइकिल आधे रास्ते पर छोड़ने से वे साथ नहीं पहुँचतीं: आशा को 4 घंटे और बीना को 2 घंटे 40 मिनट लगते, और 3 घंटे 20 मिनट उन दोनों का औसत भर है।','csat-l4-s08-qa-sdt-two-travellers-and-one-bicycle','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
One grain of sand is not a heap, and adding a single grain to something that is not a heap never seems to turn it into one. Yet if that is so, then two grains are not a heap, nor three, nor any number at all -- and heaps plainly exist. This puzzle, first posed in ancient Greece, arises with many everyday words: tall, old, poor, crowded. No single step makes a difference, but many steps together make all the difference. The law cannot wait for philosophers to settle the matter. It draws sharp lines -- a voting age of 18, a poverty line, a speed limit -- knowing that a person one day short of 18 is no less mature than one a day past it. Such lines are arbitrary at the margin, but without them every case would have to be argued afresh.

Which one of the following statements best reflects the most logical and rational message conveyed by the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
रेत का एक कण ढेर नहीं है, और जो ढेर नहीं है उसमें एक कण जोड़ने से वह कभी ढेर बनता नहीं दिखता। पर यदि ऐसा है, तो दो कण ढेर नहीं, न तीन, न कोई भी संख्या -- और ढेर तो स्पष्ट रूप से होते हैं। यह पहेली, जो पहली बार प्राचीन यूनान में उठाई गई, रोज़ के बहुत-से शब्दों के साथ उठती है: लंबा, बूढ़ा, ग़रीब, भीड़भरा। कोई एक क़दम अंतर नहीं लाता, पर बहुत-से क़दम मिलकर पूरा अंतर ला देते हैं। क़ानून दार्शनिकों के इसे सुलझाने की प्रतीक्षा नहीं कर सकता। वह तीखी रेखाएँ खींचता है -- 18 वर्ष की मतदान आयु, ग़रीबी रेखा, गति सीमा -- यह जानते हुए कि 18 से एक दिन कम का व्यक्ति एक दिन अधिक वाले से कम परिपक्व नहीं। ऐसी रेखाएँ सीमा पर मनमानी हैं, पर उनके बिना हर मामले पर नए सिरे से बहस करनी पड़ती।

निम्नलिखित में से कौन-सा कथन परिच्छेद द्वारा दिए गए सबसे तार्किक और विवेकपूर्ण संदेश को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s08", "passage_group": "csat-l4-s08-p05", "csat_order": 34}'::jsonb,'[{"id": "a", "body": "Since vague words lead to paradox, laws should stop using words such as ''poor'' or ''old''.", "body_hi": "चूँकि अस्पष्ट शब्द विरोधाभास पैदा करते हैं, क़ानूनों को ''ग़रीब'' या ''बूढ़ा'' जैसे शब्द छोड़ देने चाहिए।", "isCorrect": false}, {"id": "b", "body": "A person one day short of 18 ought to be allowed to vote, being no less mature than an adult.", "body_hi": "18 से एक दिन कम वाले व्यक्ति को मतदान करने देना चाहिए, क्योंकि वह किसी वयस्क से कम परिपक्व नहीं।", "isCorrect": false}, {"id": "c", "body": "Sharp lines in law are arbitrary at the edges, but they are needed where words are vague.", "body_hi": "क़ानून की तीखी रेखाएँ किनारों पर मनमानी हैं, पर जहाँ शब्द अस्पष्ट हों वहाँ वे आवश्यक हैं।", "isCorrect": true}, {"id": "d", "body": "Heaps do not really exist, since no single grain of sand can ever turn a pile into one.", "body_hi": "ढेर वास्तव में होते ही नहीं, क्योंकि रेत का कोई एक कण किसी अंबार को कभी ढेर नहीं बना सकता।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage grants that sharp legal lines are arbitrary at the margin, since the words they stand for are vague, and defends them as necessary: without them every case would be argued afresh. It does not ask the law to stop using vague words -- it shows how the law copes with them; it says a person a day short of 18 is no less mature, but defends the line rather than proposing to move it; and it says heaps ''plainly exist''.','परिच्छेद मानता है कि क़ानून की तीखी रेखाएँ सीमा पर मनमानी हैं, क्योंकि जिन शब्दों के लिए वे हैं वे अस्पष्ट हैं, और उन्हें आवश्यक बताकर उनका बचाव करता है: उनके बिना हर मामले पर नए सिरे से बहस होती। वह क़ानून से अस्पष्ट शब्द छोड़ने को नहीं कहता -- वह दिखाता है कि क़ानून उनसे कैसे निपटता है; वह कहता है कि 18 से एक दिन कम वाला कम परिपक्व नहीं, पर रेखा खिसकाने का प्रस्ताव नहीं, उसका बचाव करता है; और वह कहता है कि ढेर ''स्पष्ट रूप से होते हैं''।','csat-l4-s08-rc-p05-message','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
One grain of sand is not a heap, and adding a single grain to something that is not a heap never seems to turn it into one. Yet if that is so, then two grains are not a heap, nor three, nor any number at all -- and heaps plainly exist. This puzzle, first posed in ancient Greece, arises with many everyday words: tall, old, poor, crowded. No single step makes a difference, but many steps together make all the difference. The law cannot wait for philosophers to settle the matter. It draws sharp lines -- a voting age of 18, a poverty line, a speed limit -- knowing that a person one day short of 18 is no less mature than one a day past it. Such lines are arbitrary at the margin, but without them every case would have to be argued afresh.

Which one of the following is a case of the same puzzle as the one the passage describes?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
रेत का एक कण ढेर नहीं है, और जो ढेर नहीं है उसमें एक कण जोड़ने से वह कभी ढेर बनता नहीं दिखता। पर यदि ऐसा है, तो दो कण ढेर नहीं, न तीन, न कोई भी संख्या -- और ढेर तो स्पष्ट रूप से होते हैं। यह पहेली, जो पहली बार प्राचीन यूनान में उठाई गई, रोज़ के बहुत-से शब्दों के साथ उठती है: लंबा, बूढ़ा, ग़रीब, भीड़भरा। कोई एक क़दम अंतर नहीं लाता, पर बहुत-से क़दम मिलकर पूरा अंतर ला देते हैं। क़ानून दार्शनिकों के इसे सुलझाने की प्रतीक्षा नहीं कर सकता। वह तीखी रेखाएँ खींचता है -- 18 वर्ष की मतदान आयु, ग़रीबी रेखा, गति सीमा -- यह जानते हुए कि 18 से एक दिन कम का व्यक्ति एक दिन अधिक वाले से कम परिपक्व नहीं। ऐसी रेखाएँ सीमा पर मनमानी हैं, पर उनके बिना हर मामले पर नए सिरे से बहस करनी पड़ती।

निम्नलिखित में से कौन-सी स्थिति उसी पहेली का उदाहरण है जिसका परिच्छेद वर्णन करता है?','{"craft": "inference", "csat_set": "csat-l4-s08", "passage_group": "csat-l4-s08-p05", "csat_order": 35}'::jsonb,'[{"id": "a", "body": "A coin tossed many times may come up heads ten times in a row.", "body_hi": "कई बार उछाला गया सिक्का लगातार दस बार चित आ सकता है।", "isCorrect": false}, {"id": "b", "body": "A rule that applies to every citizen may still be unfair to some of them.", "body_hi": "हर नागरिक पर लागू होने वाला नियम भी उनमें से कुछ के लिए अनुचित हो सकता है।", "isCorrect": false}, {"id": "c", "body": "Two honest witnesses may describe the same event in different words.", "body_hi": "दो ईमानदार गवाह एक ही घटना का अलग-अलग शब्दों में वर्णन कर सकते हैं।", "isCorrect": false}, {"id": "d", "body": "Losing one hair never makes a person bald, yet many people are bald.", "body_hi": "एक बाल झड़ने से कोई गंजा नहीं होता, फिर भी बहुत-से लोग गंजे हैं।", "isCorrect": true}]'::jsonb,2.5,0.83,'The puzzle arises when no single small step makes a difference, yet many steps together clearly do. Losing one hair never makes a person bald, yet many people are bald: the same structure. A run of ten heads is about chance, not about a vague word; a rule unfair to some citizens is about fairness; and two witnesses using different words is about description. None involves a long series of steps that each seem to change nothing.','पहेली तब उठती है जब कोई एक छोटा क़दम अंतर नहीं लाता, फिर भी बहुत-से क़दम मिलकर स्पष्ट अंतर लाते हैं। एक बाल झड़ने से कोई गंजा नहीं होता, फिर भी बहुत-से लोग गंजे हैं: वही बनावट। लगातार दस बार चित आना संयोग के बारे में है, किसी अस्पष्ट शब्द के बारे में नहीं; कुछ नागरिकों के लिए अनुचित नियम निष्पक्षता के बारे में है; और दो गवाहों के अलग शब्द वर्णन के बारे में हैं। इनमें से किसी में ऐसे क़दमों की लंबी कड़ी नहीं जिनमें से हर एक कुछ न बदलता दिखे।','csat-l4-s08-rc-p05-the-same-puzzle-elsewhere','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Permutation & Combination','mcq','easy','Four identical counters are to be placed on the 16 squares of a 4 × 4 board so that no two of them are in the same row or in the same column. In how many ways can this be done?','चार एक जैसी गोटियों को 4 × 4 बोर्ड के 16 खानों पर इस प्रकार रखना है कि कोई दो एक ही पंक्ति या एक ही स्तंभ में न हों। यह कितने प्रकार से किया जा सकता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s08", "csat_order": 36}'::jsonb,'[{"id": "a", "body": "24", "body_hi": "24", "isCorrect": true}, {"id": "b", "body": "256", "body_hi": "256", "isCorrect": false}, {"id": "c", "body": "576", "body_hi": "576", "isCorrect": false}, {"id": "d", "body": "1,820", "body_hi": "1,820", "isCorrect": false}]'::jsonb,2.5,0.83,'Each row must hold exactly one counter. The counter in the first row can go in any of 4 columns, the one in the second row in any of the 3 columns left, then 2, then 1: 4 × 3 × 2 × 1 = 24. 1,820 is the number of ways to choose any 4 of the 16 squares, ignoring the rule; 256 = 4⁴ lets two counters share a column; 576 = 24 × 24 treats the counters as if they were different from one another.','हर पंक्ति में ठीक एक गोटी होनी चाहिए। पहली पंक्ति की गोटी 4 में से किसी भी स्तंभ में जा सकती है, दूसरी पंक्ति की बचे 3 में से किसी में, फिर 2, फिर 1: 4 × 3 × 2 × 1 = 24। 1,820, नियम की अनदेखी कर 16 में से कोई भी 4 खाने चुनने के प्रकार हैं; 256 = 4⁴ दो गोटियों को एक ही स्तंभ में आने देता है; 576 = 24 × 24 गोटियों को एक-दूसरे से भिन्न मान लेता है।','csat-l4-s08-qa-pc-four-counters-that-share-no-row-or-column','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Truth-Liar','mcq','hard','Cash has gone missing from a shop, and exactly one of P, Q, R and S took it. Three witnesses each make two statements, and each witness makes exactly one true statement and one false one.
Witness 1: ''Q did not take it.'' ''S took it.''
Witness 2: ''P did not take it.'' ''Q took it.''
Witness 3: ''P took it.'' ''Q did not take it.''
Who took the cash?','एक दुकान से नक़दी ग़ायब हो गई है, और P, Q, R और S में से ठीक एक ने उसे लिया। तीन गवाहों में से हर एक दो कथन देता है, और हर गवाह का ठीक एक कथन सच और एक झूठ है।
गवाह 1: ''Q ने नहीं लिया।'' ''S ने लिया।''
गवाह 2: ''P ने नहीं लिया।'' ''Q ने लिया।''
गवाह 3: ''P ने लिया।'' ''Q ने नहीं लिया।''
नक़दी किसने ली?','{"craft": "inference", "csat_set": "csat-l4-s08", "csat_order": 37}'::jsonb,'[{"id": "a", "body": "R", "body_hi": "R", "isCorrect": true}, {"id": "b", "body": "P", "body_hi": "P", "isCorrect": false}, {"id": "c", "body": "Q", "body_hi": "Q", "isCorrect": false}, {"id": "d", "body": "S", "body_hi": "S", "isCorrect": false}]'::jsonb,2.5,0.83,'Test each suspect. If P took it, Witness 2''s statements are both false. If Q took it, Witness 1''s are both false. If S took it, Witness 1''s are both true. If R took it, Witness 1 is right that Q did not and wrong about S; Witness 2 is right about P and wrong about Q; Witness 3 is wrong about P and right about Q -- one truth and one lie each. So R took it, though no witness names R. P, Q and S each leave some witness with two true or two false statements.','हर संदिग्ध को जाँचें। यदि P ने लिया, तो गवाह 2 के दोनों कथन झूठे हैं। यदि Q ने लिया, तो गवाह 1 के दोनों झूठे हैं। यदि S ने लिया, तो गवाह 1 के दोनों सच हैं। यदि R ने लिया, तो गवाह 1 का यह कहना सही है कि Q ने नहीं लिया और S के बारे में ग़लत; गवाह 2, P के बारे में सही और Q के बारे में ग़लत; गवाह 3, P के बारे में ग़लत और Q के बारे में सही -- हर एक का एक सच और एक झूठ। अतः R ने लिया, यद्यपि कोई गवाह R का नाम नहीं लेता। P, Q और S में से हर एक किसी गवाह के दोनों कथन सच या दोनों झूठ कर देता है।','csat-l4-s08-lr-tl-three-witnesses-who-each-tell-one-truth-and-one-lie','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','hard','a and b are positive integers whose HCF is 1. What is the HCF of a + b and ab?','a और b ऐसे धनात्मक पूर्णांक हैं जिनका म.स. (HCF) 1 है। a + b और ab का म.स. क्या है?','{"craft": "inference", "csat_set": "csat-l4-s08", "csat_order": 38}'::jsonb,'[{"id": "a", "body": "a + b", "body_hi": "a + b", "isCorrect": false}, {"id": "b", "body": "ab", "body_hi": "ab", "isCorrect": false}, {"id": "c", "body": "It depends on the values of a and b", "body_hi": "यह a और b के मानों पर निर्भर है", "isCorrect": false}, {"id": "d", "body": "1", "body_hi": "1", "isCorrect": true}]'::jsonb,2.5,0.83,'Any prime that divides ab divides a or b -- say a. If it also divided a + b, it would divide (a + b) - a = b as well, and so would divide both a and b, whose HCF is 1. So no prime divides both a + b and ab, and their HCF is 1, whatever a and b are: 4 and 9 give 13 and 36; 3 and 5 give 8 and 15. a + b would need a + b to divide ab, which fails for 4 and 9; ab would need ab to divide a + b; and the values make no difference, as the proof shows.','ab को विभाजित करने वाली कोई भी अभाज्य संख्या a या b को विभाजित करती है -- मान लें a को। यदि वह a + b को भी विभाजित करती, तो (a + b) - a = b को भी करती, और इस तरह a और b दोनों को, जिनका म.स. 1 है। इसलिए कोई अभाज्य a + b और ab दोनों को विभाजित नहीं करती, और उनका म.स. 1 है, a और b चाहे जो हों: 4 और 9 से 13 और 36 मिलते हैं; 3 और 5 से 8 और 15। a + b के लिए a + b को ab को विभाजित करना होता, जो 4 और 9 पर विफल है; ab के लिए ab को a + b को विभाजित करना होता; और जैसा प्रमाण दिखाता है, मानों से कोई अंतर नहीं पड़ता।','csat-l4-s08-qa-nt-the-hcf-of-a-sum-and-a-product','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Percentage & Profit-Loss','mcq','easy','Income tax is charged at 30% on a part of a person''s income, and a cess of 4% is then charged on the tax. What percentage of that part of the income goes in tax and cess together?','किसी व्यक्ति की आय के एक भाग पर 30% आयकर लगता है, और फिर कर पर 4% उपकर (सेस) लगता है। आय के उस भाग का कितना प्रतिशत कर और उपकर मिलाकर जाता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s08", "csat_order": 39}'::jsonb,'[{"id": "a", "body": "30.12%", "body_hi": "30.12%", "isCorrect": false}, {"id": "b", "body": "31.2%", "body_hi": "31.2%", "isCorrect": true}, {"id": "c", "body": "32%", "body_hi": "32%", "isCorrect": false}, {"id": "d", "body": "34%", "body_hi": "34%", "isCorrect": false}]'::jsonb,2.5,0.83,'The cess is 4% of the tax, not of the income: 4% of 30 = 1.2, so together they take 30 + 1.2 = 31.2% of that part of the income. 34% adds the 4 to the rate as if the cess were charged on the income; 30.12% takes 4% of 3 instead of 4% of 30; 32% has no basis.','उपकर कर का 4% है, आय का नहीं: 30 का 4% = 1.2, इसलिए दोनों मिलकर आय के उस भाग का 30 + 1.2 = 31.2% लेते हैं। 34% दर में 4 जोड़ देता है, मानो उपकर आय पर लगा हो; 30.12%, 30 के 4% के बजाय 3 का 4% लेता है; 32% का कोई आधार नहीं।','csat-l4-s08-qa-pp-a-cess-charged-on-the-tax','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In 1954 a small group in the United States came to believe, on the strength of messages its leader claimed to receive from beings in outer space, that a great flood would destroy much of the world before dawn on a set day in December, and that the faithful would be rescued by a flying saucer. Some members gave up their jobs and their possessions. The psychologist Leon Festinger and two colleagues joined the group without revealing who they were, to see what would happen when the prophecy failed. Dawn came, with no flood and no saucer. Yet the core members did not give up their belief. They announced that their faith had saved the world and began, for the first time, to seek publicity and new converts. Festinger explained this by what he called cognitive dissonance: holding beliefs that clash with each other, or with what one has done, is uncomfortable, and people often ease the discomfort by reinterpreting the evidence rather than abandoning a belief in which they have invested a great deal. Members who had waited for the end alone, away from the group, were far more likely to give the belief up.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1954 में संयुक्त राज्य अमेरिका में एक छोटे समूह ने, उन संदेशों के बल पर जिनके बारे में उसके नेता का दावा था कि वे बाहरी अंतरिक्ष के प्राणियों से मिलते हैं, यह मान लिया कि दिसंबर के एक निश्चित दिन भोर से पहले एक भीषण बाढ़ दुनिया के बड़े भाग को नष्ट कर देगी, और आस्थावानों को एक उड़नतश्तरी बचा लेगी। कुछ सदस्यों ने अपनी नौकरियाँ और अपनी संपत्ति छोड़ दी। मनोवैज्ञानिक लियोन फ़ेस्टिंगर और उनके दो सहयोगी अपनी पहचान बताए बिना समूह में शामिल हो गए, यह देखने के लिए कि भविष्यवाणी विफल होने पर क्या होगा। भोर हुई, न बाढ़ आई न उड़नतश्तरी। फिर भी मुख्य सदस्यों ने अपना विश्वास नहीं छोड़ा। उन्होंने घोषणा की कि उनकी आस्था ने दुनिया को बचा लिया है और पहली बार प्रचार और नए अनुयायी जुटाने लगे। फ़ेस्टिंगर ने इसकी व्याख्या उस बात से की जिसे उन्होंने संज्ञानात्मक असंगति कहा: ऐसे विश्वास रखना जो आपस में, या अपने किए से, टकराते हों, असहज होता है, और लोग प्रायः यह असहजता उस विश्वास को छोड़कर नहीं, जिसमें उन्होंने बहुत कुछ लगाया हो, बल्कि प्रमाण की नई व्याख्या करके दूर करते हैं। जिन सदस्यों ने समूह से दूर, अकेले अंत की प्रतीक्षा की थी, उनके विश्वास छोड़ने की संभावना कहीं अधिक थी।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s08", "passage_group": "csat-l4-s08-p06", "csat_order": 40}'::jsonb,'[{"id": "a", "body": "A refuted belief may be held more tightly, especially when others share it.", "body_hi": "खंडित विश्वास को लोग और कसकर पकड़ सकते हैं, विशेषकर जब दूसरे भी उसे मानें।", "isCorrect": true}, {"id": "b", "body": "Groups that predict the end of the world always break up once the date has passed.", "body_hi": "दुनिया के अंत की भविष्यवाणी करने वाले समूह तारीख़ बीतते ही सदा बिखर जाते हैं।", "isCorrect": false}, {"id": "c", "body": "Psychologists should never study a group of people without first telling its members.", "body_hi": "मनोवैज्ञानिकों को किसी समूह के सदस्यों को पहले बताए बिना उसका अध्ययन कभी नहीं करना चाहिए।", "isCorrect": false}, {"id": "d", "body": "People who give up their jobs for a belief are more honest than those who do not.", "body_hi": "जो लोग किसी विश्वास के लिए नौकरी छोड़ देते हैं, वे बाक़ियों से अधिक ईमानदार होते हैं।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage shows believers holding on more firmly after their prophecy failed, explains this as a way of easing an uncomfortable clash, and ends by noting that those who faced the failure alone were more likely to let go. It describes one group that did not disband, so it cannot say such groups always do; it reports Festinger''s method without judging it; and it makes no claim that people who give up jobs for a belief are more honest.','परिच्छेद दिखाता है कि भविष्यवाणी विफल होने के बाद विश्वासी और दृढ़ता से टिके रहे, इसे एक असहज टकराव को कम करने का ढंग बताता है, और यह कहकर समाप्त होता है कि विफलता का अकेले सामना करने वालों के विश्वास छोड़ने की संभावना अधिक थी। वह एक ऐसे समूह का वर्णन करता है जो बिखरा नहीं, इसलिए यह नहीं कह सकता कि ऐसे समूह सदा बिखर जाते हैं; वह फ़ेस्टिंगर की पद्धति को आँके बिना बताता है; और वह यह दावा नहीं करता कि विश्वास के लिए नौकरी छोड़ने वाले अधिक ईमानदार होते हैं।','csat-l4-s08-rc-p06-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In 1954 a small group in the United States came to believe, on the strength of messages its leader claimed to receive from beings in outer space, that a great flood would destroy much of the world before dawn on a set day in December, and that the faithful would be rescued by a flying saucer. Some members gave up their jobs and their possessions. The psychologist Leon Festinger and two colleagues joined the group without revealing who they were, to see what would happen when the prophecy failed. Dawn came, with no flood and no saucer. Yet the core members did not give up their belief. They announced that their faith had saved the world and began, for the first time, to seek publicity and new converts. Festinger explained this by what he called cognitive dissonance: holding beliefs that clash with each other, or with what one has done, is uncomfortable, and people often ease the discomfort by reinterpreting the evidence rather than abandoning a belief in which they have invested a great deal. Members who had waited for the end alone, away from the group, were far more likely to give the belief up.

What does the passage suggest about the part played by fellow believers?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1954 में संयुक्त राज्य अमेरिका में एक छोटे समूह ने, उन संदेशों के बल पर जिनके बारे में उसके नेता का दावा था कि वे बाहरी अंतरिक्ष के प्राणियों से मिलते हैं, यह मान लिया कि दिसंबर के एक निश्चित दिन भोर से पहले एक भीषण बाढ़ दुनिया के बड़े भाग को नष्ट कर देगी, और आस्थावानों को एक उड़नतश्तरी बचा लेगी। कुछ सदस्यों ने अपनी नौकरियाँ और अपनी संपत्ति छोड़ दी। मनोवैज्ञानिक लियोन फ़ेस्टिंगर और उनके दो सहयोगी अपनी पहचान बताए बिना समूह में शामिल हो गए, यह देखने के लिए कि भविष्यवाणी विफल होने पर क्या होगा। भोर हुई, न बाढ़ आई न उड़नतश्तरी। फिर भी मुख्य सदस्यों ने अपना विश्वास नहीं छोड़ा। उन्होंने घोषणा की कि उनकी आस्था ने दुनिया को बचा लिया है और पहली बार प्रचार और नए अनुयायी जुटाने लगे। फ़ेस्टिंगर ने इसकी व्याख्या उस बात से की जिसे उन्होंने संज्ञानात्मक असंगति कहा: ऐसे विश्वास रखना जो आपस में, या अपने किए से, टकराते हों, असहज होता है, और लोग प्रायः यह असहजता उस विश्वास को छोड़कर नहीं, जिसमें उन्होंने बहुत कुछ लगाया हो, बल्कि प्रमाण की नई व्याख्या करके दूर करते हैं। जिन सदस्यों ने समूह से दूर, अकेले अंत की प्रतीक्षा की थी, उनके विश्वास छोड़ने की संभावना कहीं अधिक थी।

परिच्छेद साथी विश्वासियों की भूमिका के बारे में क्या संकेत देता है?','{"craft": "inference", "csat_set": "csat-l4-s08", "passage_group": "csat-l4-s08-p06", "csat_order": 41}'::jsonb,'[{"id": "a", "body": "Their company made the members less willing to look for new converts.", "body_hi": "उनके साथ ने सदस्यों को नए अनुयायी खोजने के लिए कम इच्छुक बना दिया।", "isCorrect": false}, {"id": "b", "body": "Their company helped people keep a belief that the evidence had refuted.", "body_hi": "उनके साथ ने प्रमाण से खंडित विश्वास बनाए रखने में मदद की।", "isCorrect": true}, {"id": "c", "body": "Their company made it easier to accept that the prophecy had been false.", "body_hi": "उनके साथ ने यह मानना आसान कर दिया कि भविष्यवाणी झूठी थी।", "isCorrect": false}, {"id": "d", "body": "They mattered less than how much each member had given up for the belief.", "body_hi": "विश्वास के लिए हर सदस्य के त्याग की तुलना में उनका महत्त्व कम था।", "isCorrect": false}]'::jsonb,2.5,0.83,'Those who waited with the group mostly kept the belief; those who waited alone were far more likely to give it up. So the company of fellow believers helped people hold on to a belief the evidence had refuted. The members with the group were the ones who sought converts, not the ones made less willing; being with others made it easier to keep the belief, not to accept that it was false; and the passage gives no comparison showing that what members had given up mattered more than the group.','जिन्होंने समूह के साथ प्रतीक्षा की, उन्होंने अधिकतर विश्वास बनाए रखा; जिन्होंने अकेले प्रतीक्षा की, उनके उसे छोड़ने की संभावना कहीं अधिक थी। इसलिए साथी विश्वासियों के साथ ने लोगों को उस विश्वास पर टिके रहने में मदद की जिसका प्रमाण ने खंडन कर दिया था। समूह के साथ वाले सदस्यों ने ही अनुयायी जुटाए, वे कम इच्छुक नहीं हुए; दूसरों के साथ होने ने विश्वास बनाए रखना आसान किया, उसे झूठा मानना नहीं; और परिच्छेद ऐसी कोई तुलना नहीं देता जो दिखाए कि सदस्यों का त्याग समूह से अधिक मायने रखता था।','csat-l4-s08-rc-p06-what-fellow-believers-did','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In 1954 a small group in the United States came to believe, on the strength of messages its leader claimed to receive from beings in outer space, that a great flood would destroy much of the world before dawn on a set day in December, and that the faithful would be rescued by a flying saucer. Some members gave up their jobs and their possessions. The psychologist Leon Festinger and two colleagues joined the group without revealing who they were, to see what would happen when the prophecy failed. Dawn came, with no flood and no saucer. Yet the core members did not give up their belief. They announced that their faith had saved the world and began, for the first time, to seek publicity and new converts. Festinger explained this by what he called cognitive dissonance: holding beliefs that clash with each other, or with what one has done, is uncomfortable, and people often ease the discomfort by reinterpreting the evidence rather than abandoning a belief in which they have invested a great deal. Members who had waited for the end alone, away from the group, were far more likely to give the belief up.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1954 में संयुक्त राज्य अमेरिका में एक छोटे समूह ने, उन संदेशों के बल पर जिनके बारे में उसके नेता का दावा था कि वे बाहरी अंतरिक्ष के प्राणियों से मिलते हैं, यह मान लिया कि दिसंबर के एक निश्चित दिन भोर से पहले एक भीषण बाढ़ दुनिया के बड़े भाग को नष्ट कर देगी, और आस्थावानों को एक उड़नतश्तरी बचा लेगी। कुछ सदस्यों ने अपनी नौकरियाँ और अपनी संपत्ति छोड़ दी। मनोवैज्ञानिक लियोन फ़ेस्टिंगर और उनके दो सहयोगी अपनी पहचान बताए बिना समूह में शामिल हो गए, यह देखने के लिए कि भविष्यवाणी विफल होने पर क्या होगा। भोर हुई, न बाढ़ आई न उड़नतश्तरी। फिर भी मुख्य सदस्यों ने अपना विश्वास नहीं छोड़ा। उन्होंने घोषणा की कि उनकी आस्था ने दुनिया को बचा लिया है और पहली बार प्रचार और नए अनुयायी जुटाने लगे। फ़ेस्टिंगर ने इसकी व्याख्या उस बात से की जिसे उन्होंने संज्ञानात्मक असंगति कहा: ऐसे विश्वास रखना जो आपस में, या अपने किए से, टकराते हों, असहज होता है, और लोग प्रायः यह असहजता उस विश्वास को छोड़कर नहीं, जिसमें उन्होंने बहुत कुछ लगाया हो, बल्कि प्रमाण की नई व्याख्या करके दूर करते हैं। जिन सदस्यों ने समूह से दूर, अकेले अंत की प्रतीक्षा की थी, उनके विश्वास छोड़ने की संभावना कहीं अधिक थी।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["On Festinger''s account, the members who had given up the least for the belief would cling to it hardest.", "Seeking new converts after the failure was a way of easing the discomfort that the failure caused."], "statements_hi": ["फ़ेस्टिंगर की व्याख्या के अनुसार, विश्वास के लिए सबसे कम त्याग करने वाले सदस्य उससे सबसे अधिक चिपके रहते।", "विफलता के बाद नए अनुयायी खोजना उस असहजता को कम करने का ढंग था जो विफलता से पैदा हुई।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s08", "passage_group": "csat-l4-s08-p06", "csat_order": 42}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Only 2 is valid. The passage explains the new search for publicity and converts by cognitive dissonance: winning others to the belief eased the discomfort of a failed prophecy. 1 reverses Festinger''s account: on it, the more a member had invested in the belief, the harder it was to abandon, so those who had given up the least would cling least, not hardest.','केवल 2 वैध है। परिच्छेद प्रचार और अनुयायियों की नई खोज की व्याख्या संज्ञानात्मक असंगति से करता है: दूसरों को विश्वास में लाने से विफल भविष्यवाणी की असहजता कम हुई। 1 फ़ेस्टिंगर की व्याख्या को उलट देता है: उसके अनुसार सदस्य ने विश्वास में जितना अधिक लगाया था, उसे छोड़ना उतना कठिन था, इसलिए सबसे कम त्याग करने वाले सबसे कम चिपकते, सबसे अधिक नहीं।','csat-l4-s08-rc-p06-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Ratio, Mixtures & Alligation','mcq','medium','A farmer has to apply 120 kg of nitrogen per hectare to a field of 0.75 hectare, using urea, which is 46% nitrogen by weight. Urea is sold only in whole bags of 45 kg. How many bags must the farmer buy?','एक किसान को 0.75 हेक्टेयर के खेत में प्रति हेक्टेयर 120 किग्रा नाइट्रोजन यूरिया के रूप में डालनी है, जिसमें भार के अनुसार 46% नाइट्रोजन होती है। यूरिया केवल 45 किग्रा की पूरी बोरियों में बिकता है। किसान को कितनी बोरियाँ ख़रीदनी होंगी?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s08", "csat_order": 43}'::jsonb,'[{"id": "a", "body": "2", "body_hi": "2", "isCorrect": false}, {"id": "b", "body": "3", "body_hi": "3", "isCorrect": false}, {"id": "c", "body": "4", "body_hi": "4", "isCorrect": false}, {"id": "d", "body": "5", "body_hi": "5", "isCorrect": true}]'::jsonb,2.5,0.83,'The field needs 120 × 0.75 = 90 kg of nitrogen. Since urea is 46% nitrogen, that takes 90 ÷ 0.46 ≈ 195.7 kg of urea, or 195.7 ÷ 45 ≈ 4.35 bags -- so 5 whole bags. 4 rounds down and leaves the field short of nitrogen; 2 forgets that urea is only 46% nitrogen (90 ÷ 45); 3 forgets that and the field''s size as well (120 ÷ 45 ≈ 2.7, rounded up).','खेत को 120 × 0.75 = 90 किग्रा नाइट्रोजन चाहिए। यूरिया में 46% नाइट्रोजन है, इसलिए 90 ÷ 0.46 ≈ 195.7 किग्रा यूरिया लगेगा, यानी 195.7 ÷ 45 ≈ 4.35 बोरियाँ -- अतः 5 पूरी बोरियाँ। 4 नीचे की ओर पूर्णांक बनाता है और खेत में नाइट्रोजन कम रह जाती है; 2 भूल जाता है कि यूरिया में केवल 46% नाइट्रोजन है (90 ÷ 45); 3 यह और खेत का आकार, दोनों भूल जाता है (120 ÷ 45 ≈ 2.7, ऊपर की ओर पूर्णांक)।','csat-l4-s08-qa-rm-urea-bought-by-the-bag','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Statement-Conclusion/Assumption','mcq','hard','''Districts in which a larger share of women can read and write have, on average, fewer children per woman. So in any district, a woman who can read and write will have fewer children than a woman who cannot.'' Which one of the following best describes the flaw in this reasoning?','''जिन ज़िलों में पढ़-लिख सकने वाली महिलाओं का अनुपात अधिक है, वहाँ औसतन प्रति महिला बच्चे कम हैं। इसलिए किसी भी ज़िले में, पढ़-लिख सकने वाली महिला के बच्चे न पढ़-लिख सकने वाली महिला से कम होंगे।'' निम्नलिखित में से कौन-सा इस तर्क की त्रुटि का सबसे अच्छा वर्णन करता है?','{"craft": "inference", "csat_set": "csat-l4-s08", "csat_order": 44}'::jsonb,'[{"id": "a", "body": "It assumes that being able to read is the only reason why families have fewer children.", "body_hi": "यह मान लेता है कि पढ़ पाना ही वह अकेला कारण है जिससे परिवारों में बच्चे कम होते हैं।", "isCorrect": false}, {"id": "b", "body": "It applies a pattern found among whole districts to every woman within a district.", "body_hi": "यह पूरे ज़िलों के बीच पाए गए पैटर्न को किसी ज़िले की हर महिला पर लागू कर देता है।", "isCorrect": true}, {"id": "c", "body": "It treats the average number of children in a district as if it were the largest number there.", "body_hi": "यह किसी ज़िले में बच्चों की औसत संख्या को ऐसे लेता है मानो वह वहाँ की सबसे बड़ी संख्या हो।", "isCorrect": false}, {"id": "d", "body": "It uses figures about women in order to reach a conclusion about the men in those districts.", "body_hi": "यह महिलाओं के आँकड़ों से उन ज़िलों के पुरुषों के बारे में निष्कर्ष निकालता है।", "isCorrect": false}]'::jsonb,2.5,0.83,'The evidence compares districts as wholes; it says nothing about how individual women within a district compare, still less that every literate woman will have fewer children than every woman who is not. A pattern among groups need not hold for each member of them. The argument makes no claim that literacy is the only cause; it does not mistake an average for a maximum; and its conclusion is about women, not men.','प्रमाण पूरे ज़िलों की तुलना करता है; वह यह नहीं बताता कि किसी ज़िले के भीतर अलग-अलग महिलाओं की तुलना कैसी है, यह तो बिल्कुल नहीं कि हर साक्षर महिला के बच्चे हर निरक्षर महिला से कम होंगे। समूहों के बीच का पैटर्न उनके हर सदस्य पर लागू हो, यह आवश्यक नहीं। तर्क यह दावा नहीं करता कि साक्षरता ही अकेला कारण है; वह औसत को अधिकतम नहीं समझता; और उसका निष्कर्ष महिलाओं के बारे में है, पुरुषों के नहीं।','csat-l4-s08-lr-sc-a-pattern-among-districts-applied-to-each-woman','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','medium','A three-digit number has the digits a, b and c, none of them zero. It is added to the two numbers formed by moving its digits round, to give abc + bca + cab (for example, 125 + 251 + 512). Which one of the following numbers always divides this sum?','तीन अंकों की एक संख्या के अंक a, b और c हैं, जिनमें कोई शून्य नहीं। उसमें उसके अंकों को घुमाकर बनी दो संख्याएँ जोड़ी जाती हैं, जिससे abc + bca + cab मिलता है (उदाहरण के लिए, 125 + 251 + 512)। निम्नलिखित में से कौन-सी संख्या इस योग को सदा विभाजित करती है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s08", "csat_order": 45}'::jsonb,'[{"id": "a", "body": "11", "body_hi": "11", "isCorrect": false}, {"id": "b", "body": "27", "body_hi": "27", "isCorrect": false}, {"id": "c", "body": "37", "body_hi": "37", "isCorrect": true}, {"id": "d", "body": "99", "body_hi": "99", "isCorrect": false}]'::jsonb,2.5,0.83,'Each of a, b and c stands once in the hundreds place, once in the tens and once in the units, so the sum is 111a + 111b + 111c = 111(a + b + c) = 3 × 37 × (a + b + c). So 37 always divides it: 125 + 251 + 512 = 888 = 37 × 24. 27 divides it only when a + b + c is a multiple of 9, and 11 and 99 only when 11 divides a + b + c; the example 888 is a multiple of none of them.','a, b और c में से हर अंक एक बार सैकड़े, एक बार दहाई और एक बार इकाई के स्थान पर आता है, इसलिए योग 111a + 111b + 111c = 111(a + b + c) = 3 × 37 × (a + b + c) है। अतः 37 इसे सदा विभाजित करता है: 125 + 251 + 512 = 888 = 37 × 24। 27 इसे तभी विभाजित करता है जब a + b + c, 9 का गुणज हो, और 11 तथा 99 तभी जब 11, a + b + c को विभाजित करे; उदाहरण का 888 इनमें से किसी का गुणज नहीं।','csat-l4-s08-qa-nt-a-number-added-to-its-two-rotations','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Data Sufficiency','mcq','hard','The item below contains a question followed by two statements. Decide whether the data in the statements are sufficient to answer the question.

Question: Does triangle ABC have at least two equal sides?','नीचे दिए गए प्रश्नांश में एक प्रश्न और उसके बाद दो कथन हैं। तय कीजिए कि कथनों में दिए गए आँकड़े प्रश्न का उत्तर देने के लिए पर्याप्त हैं या नहीं।

प्रश्न: क्या त्रिभुज ABC की कम से कम दो भुजाएँ बराबर हैं?','{"statements": ["Two of its angles are 50° and 80°.", "Its perimeter is three times its shortest side."], "statements_hi": ["उसके दो कोण 50° और 80° हैं।", "उसका परिमाप उसकी सबसे छोटी भुजा का तीन गुना है।"], "numbering": "roman", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s08", "csat_order": 46}'::jsonb,'[{"id": "a", "body": "The question can be answered using one of the statements alone, but not using the other statement alone", "body_hi": "प्रश्न का उत्तर किसी एक कथन के आधार पर अकेले दिया जा सकता है, पर दूसरे कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "b", "body": "The question can be answered using either statement alone", "body_hi": "प्रश्न का उत्तर किसी भी एक कथन के आधार पर अकेले दिया जा सकता है", "isCorrect": true}, {"id": "c", "body": "The question can be answered using both the statements together, but not using either statement alone", "body_hi": "प्रश्न का उत्तर दोनों कथनों को साथ लेकर दिया जा सकता है, पर किसी भी एक कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "d", "body": "The question cannot be answered even using both the statements together", "body_hi": "दोनों कथनों को साथ लेकर भी प्रश्न का उत्तर नहीं दिया जा सकता", "isCorrect": false}]'::jsonb,2.5,0.83,'Statement I alone: the third angle is 180° - 50° - 80° = 50°, so two angles are equal, and the sides opposite them are equal -- yes. Statement II alone: the other two sides are each at least as long as the shortest, so all three add up to three times the shortest only if both equal it. The triangle is equilateral, so it certainly has two equal sides -- yes. Either statement alone answers the question.','कथन I अकेले: तीसरा कोण 180° - 50° - 80° = 50° है, इसलिए दो कोण बराबर हैं, और उनके सामने की भुजाएँ बराबर हैं -- हाँ। कथन II अकेले: बाक़ी दोनों भुजाएँ सबसे छोटी भुजा जितनी लंबी तो हैं ही, इसलिए तीनों का योग सबसे छोटी का तीन गुना तभी होगा जब दोनों उसके बराबर हों। त्रिभुज समबाहु है, इसलिए उसकी दो भुजाएँ निश्चित रूप से बराबर हैं -- हाँ। कोई भी एक कथन अकेले प्रश्न का उत्तर देता है।','csat-l4-s08-qa-ds-two-equal-sides-from-the-angles-or-the-perimeter','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Data Sufficiency','mcq','medium','The item below contains a question followed by two statements. Decide whether the data in the statements are sufficient to answer the question.

Question: What is the HCF of the positive integers a and b?','नीचे दिए गए प्रश्नांश में एक प्रश्न और उसके बाद दो कथन हैं। तय कीजिए कि कथनों में दिए गए आँकड़े प्रश्न का उत्तर देने के लिए पर्याप्त हैं या नहीं।

प्रश्न: धनात्मक पूर्णांकों a और b का म.स. (HCF) क्या है?','{"statements": ["a = 3b.", "b = 12."], "statements_hi": ["a = 3b।", "b = 12।"], "numbering": "roman", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s08", "csat_order": 47}'::jsonb,'[{"id": "a", "body": "The question can be answered using one of the statements alone, but not using the other statement alone", "body_hi": "प्रश्न का उत्तर किसी एक कथन के आधार पर अकेले दिया जा सकता है, पर दूसरे कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "b", "body": "The question can be answered using either statement alone", "body_hi": "प्रश्न का उत्तर किसी भी एक कथन के आधार पर अकेले दिया जा सकता है", "isCorrect": false}, {"id": "c", "body": "The question can be answered using both the statements together, but not using either statement alone", "body_hi": "प्रश्न का उत्तर दोनों कथनों को साथ लेकर दिया जा सकता है, पर किसी भी एक कथन के आधार पर अकेले नहीं", "isCorrect": true}, {"id": "d", "body": "The question cannot be answered even using both the statements together", "body_hi": "दोनों कथनों को साथ लेकर भी प्रश्न का उत्तर नहीं दिया जा सकता", "isCorrect": false}]'::jsonb,2.5,0.83,'Statement I alone shows that b divides a, so the HCF is b itself -- but it does not say what b is, so it gives no number. Statement II alone says nothing about a. Together, a = 36 and b = 12, and the HCF is 12. Both statements are needed.','कथन I अकेले दिखाता है कि b, a को विभाजित करता है, इसलिए म.स. स्वयं b है -- पर वह यह नहीं बताता कि b क्या है, इसलिए कोई संख्या नहीं मिलती। कथन II अकेले a के बारे में कुछ नहीं कहता। दोनों मिलकर a = 36 और b = 12, और म.स. 12 है। दोनों कथन आवश्यक हैं।','csat-l4-s08-qa-ds-an-hcf-that-is-left-as-a-letter','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Data Sufficiency','mcq','medium','The item below contains a question followed by two statements. Decide whether the data in the statements are sufficient to answer the question.

Question: There are three boxes: red, blue and green. Is the red box heavier than the blue box?','नीचे दिए गए प्रश्नांश में एक प्रश्न और उसके बाद दो कथन हैं। तय कीजिए कि कथनों में दिए गए आँकड़े प्रश्न का उत्तर देने के लिए पर्याप्त हैं या नहीं।

प्रश्न: तीन डिब्बे हैं: लाल, नीला और हरा। क्या लाल डिब्बा नीले डिब्बे से भारी है?','{"statements": ["The red and green boxes together are heavier than the blue and green boxes together.", "The red box is heavier than the green box, and the green box is heavier than the blue box."], "statements_hi": ["लाल और हरा डिब्बा मिलकर नीले और हरे डिब्बे से मिलकर भारी हैं।", "लाल डिब्बा हरे से भारी है, और हरा डिब्बा नीले से भारी है।"], "numbering": "roman", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s08", "csat_order": 48}'::jsonb,'[{"id": "a", "body": "The question can be answered using one of the statements alone, but not using the other statement alone", "body_hi": "प्रश्न का उत्तर किसी एक कथन के आधार पर अकेले दिया जा सकता है, पर दूसरे कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "b", "body": "The question can be answered using either statement alone", "body_hi": "प्रश्न का उत्तर किसी भी एक कथन के आधार पर अकेले दिया जा सकता है", "isCorrect": true}, {"id": "c", "body": "The question can be answered using both the statements together, but not using either statement alone", "body_hi": "प्रश्न का उत्तर दोनों कथनों को साथ लेकर दिया जा सकता है, पर किसी भी एक कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "d", "body": "The question cannot be answered even using both the statements together", "body_hi": "दोनों कथनों को साथ लेकर भी प्रश्न का उत्तर नहीं दिया जा सकता", "isCorrect": false}]'::jsonb,2.5,0.83,'Statement I alone: the green box is on both sides, so taking it away from both leaves the red box heavier than the blue -- yes. Statement II alone: red is heavier than green, which is heavier than blue, so red is heavier than blue -- yes. Either statement alone answers the question.','कथन I अकेले: हरा डिब्बा दोनों ओर है, इसलिए दोनों ओर से उसे हटाने पर लाल डिब्बा नीले से भारी बचता है -- हाँ। कथन II अकेले: लाल, हरे से भारी है, जो नीले से भारी है, इसलिए लाल, नीले से भारी है -- हाँ। कोई भी एक कथन अकेले प्रश्न का उत्तर देता है।','csat-l4-s08-lr-ds-a-weight-on-both-pans','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Logical Reasoning','Data Sufficiency','mcq','medium','The item below contains a question followed by two statements. Decide whether the data in the statements are sufficient to answer the question.

Question: Ravi is a man. Is Ravi an uncle of Sita?','नीचे दिए गए प्रश्नांश में एक प्रश्न और उसके बाद दो कथन हैं। तय कीजिए कि कथनों में दिए गए आँकड़े प्रश्न का उत्तर देने के लिए पर्याप्त हैं या नहीं।

प्रश्न: रवि एक पुरुष है। क्या रवि, सीता का अंकल (चाचा, ताऊ, मामा, मौसा या फूफा) है?','{"statements": ["Ravi is the brother of Sita''s mother.", "Ravi''s father is Sita''s grandfather."], "statements_hi": ["रवि, सीता की माँ का भाई है।", "रवि के पिता, सीता के दादा/नाना हैं।"], "numbering": "roman", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s08", "csat_order": 49}'::jsonb,'[{"id": "a", "body": "The question can be answered using one of the statements alone, but not using the other statement alone", "body_hi": "प्रश्न का उत्तर किसी एक कथन के आधार पर अकेले दिया जा सकता है, पर दूसरे कथन के आधार पर अकेले नहीं", "isCorrect": true}, {"id": "b", "body": "The question can be answered using either statement alone", "body_hi": "प्रश्न का उत्तर किसी भी एक कथन के आधार पर अकेले दिया जा सकता है", "isCorrect": false}, {"id": "c", "body": "The question can be answered using both the statements together, but not using either statement alone", "body_hi": "प्रश्न का उत्तर दोनों कथनों को साथ लेकर दिया जा सकता है, पर किसी भी एक कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "d", "body": "The question cannot be answered even using both the statements together", "body_hi": "दोनों कथनों को साथ लेकर भी प्रश्न का उत्तर नहीं दिया जा सकता", "isCorrect": false}]'::jsonb,2.5,0.83,'Statement I alone: the brother of Sita''s mother is her maternal uncle -- yes. Statement II alone: a son of Sita''s grandfather may be Sita''s own father, or her father''s or mother''s brother, so the answer could be yes or no. One statement alone is enough, but not the other.','कथन I अकेले: सीता की माँ का भाई उसका मामा है -- हाँ। कथन II अकेले: सीता के दादा/नाना का बेटा स्वयं सीता का पिता हो सकता है, या उसके पिता या माँ का भाई, इसलिए उत्तर हाँ या नहीं, दोनों हो सकता है। एक कथन अकेले पर्याप्त है, पर दूसरा नहीं।','csat-l4-s08-lr-ds-an-uncle-found-two-ways','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Logical Reasoning','Data Sufficiency','mcq','hard','The item below contains a question followed by two statements. Decide whether the data in the statements are sufficient to answer the question.

Question: A long row of letters follows a pattern that repeats. What is the 20th letter of the row?','नीचे दिए गए प्रश्नांश में एक प्रश्न और उसके बाद दो कथन हैं। तय कीजिए कि कथनों में दिए गए आँकड़े प्रश्न का उत्तर देने के लिए पर्याप्त हैं या नहीं।

प्रश्न: अक्षरों की एक लंबी पंक्ति एक दोहराने वाले पैटर्न पर चलती है। पंक्ति का 20वाँ अक्षर क्या है?','{"statements": ["The pattern repeats every 6 letters.", "The 2nd, 8th and 14th letters are all K."], "statements_hi": ["पैटर्न हर 6 अक्षरों के बाद दोहराता है।", "दूसरा, आठवाँ और चौदहवाँ अक्षर, तीनों K हैं।"], "numbering": "roman", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s08", "csat_order": 50}'::jsonb,'[{"id": "a", "body": "The question can be answered using one of the statements alone, but not using the other statement alone", "body_hi": "प्रश्न का उत्तर किसी एक कथन के आधार पर अकेले दिया जा सकता है, पर दूसरे कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "b", "body": "The question can be answered using either statement alone", "body_hi": "प्रश्न का उत्तर किसी भी एक कथन के आधार पर अकेले दिया जा सकता है", "isCorrect": false}, {"id": "c", "body": "The question can be answered using both the statements together, but not using either statement alone", "body_hi": "प्रश्न का उत्तर दोनों कथनों को साथ लेकर दिया जा सकता है, पर किसी भी एक कथन के आधार पर अकेले नहीं", "isCorrect": true}, {"id": "d", "body": "The question cannot be answered even using both the statements together", "body_hi": "दोनों कथनों को साथ लेकर भी प्रश्न का उत्तर नहीं दिया जा सकता", "isCorrect": false}]'::jsonb,2.5,0.83,'Statement I alone gives the length of the pattern but none of its letters. Statement II alone gives three letters but not the length: a pattern of 6 would put K 20th too, but with a 7-letter pattern, for instance, the K''s at places 2, 8 and 14 fix only three of its letters, and the 20th letter falls on one that is still free. Together: with a 6-letter pattern the 20th letter stands where the 2nd, 8th and 14th do (20 = 2 + 3 × 6), so it is K. Both statements are needed.','कथन I अकेले पैटर्न की लंबाई बताता है पर उसका कोई अक्षर नहीं। कथन II अकेले तीन अक्षर बताता है पर लंबाई नहीं: 6 का पैटर्न 20वें स्थान पर भी K रखता, पर, उदाहरण के लिए, 7 अक्षरों के पैटर्न में स्थान 2, 8 और 14 के K उसके केवल तीन अक्षर तय करते हैं, और 20वाँ अक्षर किसी ऐसे अक्षर पर पड़ता है जो अभी अनिर्धारित है। दोनों मिलकर: 6 अक्षरों के पैटर्न में 20वाँ अक्षर उसी स्थान पर पड़ता है जहाँ दूसरा, आठवाँ और चौदहवाँ (20 = 2 + 3 × 6), इसलिए वह K है। दोनों कथन आवश्यक हैं।','csat-l4-s08-lr-ds-the-20th-letter-of-a-pattern-that-repeats','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','easy','The letters a, b, c, ..., z stand for 26 numbers, one for each letter of the alphabet. What is the value of the product (x - a)(x - b)(x - c) ... (x - z), which has one factor for every letter?','अक्षर a, b, c, ..., z, वर्णमाला के हर अक्षर के लिए एक, कुल 26 संख्याओं को दर्शाते हैं। गुणनफल (x - a)(x - b)(x - c) ... (x - z) का मान क्या है, जिसमें हर अक्षर के लिए एक गुणनखंड है?','{"craft": "inference", "csat_set": "csat-l4-s08", "csat_order": 51}'::jsonb,'[{"id": "a", "body": "0", "body_hi": "0", "isCorrect": true}, {"id": "b", "body": "1", "body_hi": "1", "isCorrect": false}, {"id": "c", "body": "x²⁶", "body_hi": "x²⁶", "isCorrect": false}, {"id": "d", "body": "It cannot be found unless the 26 numbers are known", "body_hi": "26 संख्याएँ जाने बिना इसे नहीं निकाला जा सकता", "isCorrect": false}]'::jsonb,2.5,0.83,'x is itself one of the letters, so one of the 26 factors is (x - x) = 0, and a product with a zero factor is 0, whatever the other numbers are. 1 and x²⁶ treat the factors as if they cancelled out or as if every other letter stood for 0; and the 26 numbers are not needed, because the single zero factor settles the product.','x स्वयं भी एक अक्षर है, इसलिए 26 गुणनखंडों में से एक (x - x) = 0 है, और जिस गुणनफल में एक गुणनखंड शून्य हो वह 0 होता है, बाक़ी संख्याएँ चाहे जो हों। 1 और x²⁶ गुणनखंडों को ऐसे लेते हैं मानो वे कट जाते हों या हर दूसरा अक्षर 0 हो; और 26 संख्याओं की आवश्यकता नहीं, क्योंकि एक शून्य गुणनखंड ही गुणनफल तय कर देता है।','csat-l4-s08-qa-nt-a-product-with-a-zero-factor-hidden-in-it','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In the late nineteenth century Dadabhai Naoroji set out to measure the poverty of India. Working from official figures, he estimated that income per head was only about 20 rupees a year -- too little, he argued, to keep a labourer in the barest health. His explanation became known as the drain of wealth. Every year a large part of India''s revenue left the country for Britain without any return: as the salaries and pensions of British officials, as interest on public debt, and as the ''home charges'' of the government of India in London. A country that sends abroad each year a share of what it produces, he argued, cannot build up the capital it needs to grow. His book, Poverty and Un-British Rule in India, was published in 1901. Its title made his point: he did not reject the British ideals of justice and fair dealing, but accused British rule in India of betraying them. Later historians have disputed his figures, but the idea of the drain gave the national movement an economic charge against colonial rule that did not rest on sentiment alone.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
उन्नीसवीं सदी के उत्तरार्ध में दादाभाई नौरोजी ने भारत की ग़रीबी मापने का प्रयास किया। सरकारी आँकड़ों के आधार पर उन्होंने अनुमान लगाया कि प्रति व्यक्ति आय केवल लगभग 20 रुपये वार्षिक थी -- उनके तर्क में, एक मज़दूर को न्यूनतम स्वस्थ रखने के लिए भी बहुत कम। उनकी व्याख्या धन के निकास (ड्रेन ऑफ़ वेल्थ) के नाम से जानी गई। हर वर्ष भारत के राजस्व का एक बड़ा भाग बिना किसी प्रतिफल के देश से ब्रिटेन चला जाता था: ब्रिटिश अधिकारियों के वेतन और पेंशन के रूप में, सार्वजनिक ऋण पर ब्याज के रूप में, और लंदन में भारत सरकार के ''होम चार्जेज़'' के रूप में। उनका तर्क था कि जो देश हर वर्ष अपने उत्पादन का एक भाग विदेश भेजता है, वह बढ़ने के लिए आवश्यक पूँजी नहीं जुटा सकता। उनकी पुस्तक, पॉवर्टी एंड अन-ब्रिटिश रूल इन इंडिया, 1901 में प्रकाशित हुई। उसका शीर्षक ही उनकी बात कहता था: वे न्याय और निष्पक्ष व्यवहार के ब्रिटिश आदर्शों को अस्वीकार नहीं करते थे, बल्कि भारत में ब्रिटिश शासन पर उन आदर्शों से विश्वासघात का आरोप लगाते थे। बाद के इतिहासकारों ने उनके आँकड़ों पर विवाद किया है, पर निकास के विचार ने राष्ट्रीय आंदोलन को औपनिवेशिक शासन के विरुद्ध एक ऐसा आर्थिक आरोप दिया जो केवल भावना पर नहीं टिका था।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s08", "passage_group": "csat-l4-s08-p07", "csat_order": 52}'::jsonb,'[{"id": "a", "body": "Naoroji proved beyond all dispute that India''s income per head was exactly 20 rupees a year.", "body_hi": "नौरोजी ने निर्विवाद रूप से सिद्ध किया कि भारत की प्रति व्यक्ति आय ठीक 20 रुपये वार्षिक थी।", "isCorrect": false}, {"id": "b", "body": "Naoroji rejected British ideas of justice and fair dealing as being unsuited to India.", "body_hi": "नौरोजी ने न्याय और निष्पक्ष व्यवहार के ब्रिटिश विचारों को भारत के लिए अनुपयुक्त बताकर अस्वीकार किया।", "isCorrect": false}, {"id": "c", "body": "India was poor mainly because its own people chose to send their savings abroad of their own free will.", "body_hi": "भारत मुख्यतः इसलिए ग़रीब था कि उसके लोग अपनी इच्छा से अपनी बचत विदेश भेजते थे।", "isCorrect": false}, {"id": "d", "body": "Naoroji blamed India''s poverty on a yearly drain of wealth, giving nationalists an economic case.", "body_hi": "नौरोजी ने ग़रीबी को धन के वार्षिक निकास से जोड़ा, जिससे राष्ट्रवादियों को आर्थिक तर्क मिला।", "isCorrect": true}]'::jsonb,2.5,0.83,'The passage presents Naoroji''s case that a yearly outflow of wealth without return kept India poor, and ends with its significance: whatever the disputes over his figures, it gave the national movement an economic case against colonial rule. His figures are said to be disputed, not proved beyond dispute; he appealed to British ideals rather than rejecting them; and the drain was made up of official payments, not of Indians choosing to send their savings abroad.','परिच्छेद नौरोजी का यह तर्क रखता है कि बिना प्रतिफल के धन के वार्षिक बहिर्गमन ने भारत को ग़रीब रखा, और उसके महत्त्व पर समाप्त होता है: उनके आँकड़ों पर विवाद जो भी हो, इसने राष्ट्रीय आंदोलन को औपनिवेशिक शासन के विरुद्ध आर्थिक तर्क दिया। उनके आँकड़ों को विवादित कहा गया है, निर्विवाद रूप से सिद्ध नहीं; उन्होंने ब्रिटिश आदर्शों को अस्वीकार नहीं किया, उनकी दुहाई दी; और निकास सरकारी भुगतानों से बना था, भारतीयों द्वारा अपनी इच्छा से बचत विदेश भेजने से नहीं।','csat-l4-s08-rc-p07-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In the late nineteenth century Dadabhai Naoroji set out to measure the poverty of India. Working from official figures, he estimated that income per head was only about 20 rupees a year -- too little, he argued, to keep a labourer in the barest health. His explanation became known as the drain of wealth. Every year a large part of India''s revenue left the country for Britain without any return: as the salaries and pensions of British officials, as interest on public debt, and as the ''home charges'' of the government of India in London. A country that sends abroad each year a share of what it produces, he argued, cannot build up the capital it needs to grow. His book, Poverty and Un-British Rule in India, was published in 1901. Its title made his point: he did not reject the British ideals of justice and fair dealing, but accused British rule in India of betraying them. Later historians have disputed his figures, but the idea of the drain gave the national movement an economic charge against colonial rule that did not rest on sentiment alone.

Which one of the following can be inferred about the way Naoroji argued his case?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
उन्नीसवीं सदी के उत्तरार्ध में दादाभाई नौरोजी ने भारत की ग़रीबी मापने का प्रयास किया। सरकारी आँकड़ों के आधार पर उन्होंने अनुमान लगाया कि प्रति व्यक्ति आय केवल लगभग 20 रुपये वार्षिक थी -- उनके तर्क में, एक मज़दूर को न्यूनतम स्वस्थ रखने के लिए भी बहुत कम। उनकी व्याख्या धन के निकास (ड्रेन ऑफ़ वेल्थ) के नाम से जानी गई। हर वर्ष भारत के राजस्व का एक बड़ा भाग बिना किसी प्रतिफल के देश से ब्रिटेन चला जाता था: ब्रिटिश अधिकारियों के वेतन और पेंशन के रूप में, सार्वजनिक ऋण पर ब्याज के रूप में, और लंदन में भारत सरकार के ''होम चार्जेज़'' के रूप में। उनका तर्क था कि जो देश हर वर्ष अपने उत्पादन का एक भाग विदेश भेजता है, वह बढ़ने के लिए आवश्यक पूँजी नहीं जुटा सकता। उनकी पुस्तक, पॉवर्टी एंड अन-ब्रिटिश रूल इन इंडिया, 1901 में प्रकाशित हुई। उसका शीर्षक ही उनकी बात कहता था: वे न्याय और निष्पक्ष व्यवहार के ब्रिटिश आदर्शों को अस्वीकार नहीं करते थे, बल्कि भारत में ब्रिटिश शासन पर उन आदर्शों से विश्वासघात का आरोप लगाते थे। बाद के इतिहासकारों ने उनके आँकड़ों पर विवाद किया है, पर निकास के विचार ने राष्ट्रीय आंदोलन को औपनिवेशिक शासन के विरुद्ध एक ऐसा आर्थिक आरोप दिया जो केवल भावना पर नहीं टिका था।

नौरोजी ने अपना पक्ष जिस ढंग से रखा, उसके बारे में निम्नलिखित में से कौन-सा निष्कर्ष निकाला जा सकता है?','{"craft": "inference", "csat_set": "csat-l4-s08", "passage_group": "csat-l4-s08-p07", "csat_order": 53}'::jsonb,'[{"id": "a", "body": "He held that India should cut every one of its ties with Britain at once.", "body_hi": "उनका मत था कि भारत को ब्रिटेन से अपना हर संबंध तुरंत तोड़ लेना चाहिए।", "isCorrect": false}, {"id": "b", "body": "He relied on feeling far more than on figures to make his case against the rule.", "body_hi": "शासन के विरुद्ध अपना पक्ष रखने में वे आँकड़ों से कहीं अधिक भावना पर निर्भर रहे।", "isCorrect": false}, {"id": "c", "body": "He judged British rule by the standards that its own rulers claimed to uphold.", "body_hi": "उन्होंने ब्रिटिश शासन को उसके शासकों के अपने घोषित मानकों पर परखा।", "isCorrect": true}, {"id": "d", "body": "He blamed India''s poverty mainly on the great size of its growing population.", "body_hi": "उन्होंने भारत की ग़रीबी का मुख्य दोष उसकी बढ़ती जनसंख्या के बड़े आकार को दिया।", "isCorrect": false}]'::jsonb,2.5,0.83,'The title ''Un-British Rule'' and the passage''s gloss on it show that Naoroji measured British rule in India against ideals the British themselves professed -- justice and fair dealing -- and found it wanting. He did not reject British ideals, so a call to cut every tie at once does not follow; he worked from official figures, and the passage says his case did not rest on sentiment alone; and he blamed the drain, not the size of the population.','शीर्षक ''अन-ब्रिटिश रूल'' और परिच्छेद में उसकी व्याख्या दिखाती है कि नौरोजी ने भारत में ब्रिटिश शासन को उन आदर्शों -- न्याय और निष्पक्ष व्यवहार -- की कसौटी पर परखा जिनका दावा स्वयं ब्रिटिश करते थे, और उसे खरा नहीं पाया। उन्होंने ब्रिटिश आदर्शों को अस्वीकार नहीं किया, इसलिए हर संबंध तुरंत तोड़ने की माँग का निष्कर्ष नहीं निकलता; उन्होंने सरकारी आँकड़ों से काम किया, और परिच्छेद कहता है कि उनका तर्क केवल भावना पर नहीं टिका था; और उन्होंने दोष निकास को दिया, जनसंख्या के आकार को नहीं।','csat-l4-s08-rc-p07-how-naoroji-argued','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In the late nineteenth century Dadabhai Naoroji set out to measure the poverty of India. Working from official figures, he estimated that income per head was only about 20 rupees a year -- too little, he argued, to keep a labourer in the barest health. His explanation became known as the drain of wealth. Every year a large part of India''s revenue left the country for Britain without any return: as the salaries and pensions of British officials, as interest on public debt, and as the ''home charges'' of the government of India in London. A country that sends abroad each year a share of what it produces, he argued, cannot build up the capital it needs to grow. His book, Poverty and Un-British Rule in India, was published in 1901. Its title made his point: he did not reject the British ideals of justice and fair dealing, but accused British rule in India of betraying them. Later historians have disputed his figures, but the idea of the drain gave the national movement an economic charge against colonial rule that did not rest on sentiment alone.

